    function decode64(input){
        var k="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/=";
        var o="",c1,c2,c3,e1,e2,e3,e4,i=0; input=input.replace(/[^A-Za-z0-9\+\/\=]/g,"");
        while(i<input.length){ e1=k.indexOf(input.charAt(i++)); e2=k.indexOf(input.charAt(i++));
            e3=k.indexOf(input.charAt(i++)); e4=k.indexOf(input.charAt(i++));
            c1=(e1<<2)|(e2>>4); c2=((e2&15)<<4)|(e3>>2); c3=((e3&3)<<6)|e4;
            o+=String.fromCharCode(c1); if(e3!=64)o+=String.fromCharCode(c2); if(e4!=64)o+=String.fromCharCode(c3); }
        return o;
    }
    function writeText(f,txt){ f.encoding="UTF-8"; f.lineFeed=(($.os.indexOf("Windows")!=-1)?"Windows":"Unix"); f.open("w"); f.write(txt); f.close(); }
    function writeUTF8(f,txt){ f.encoding="UTF-8"; f.lineFeed="Unix"; f.open("w"); f.write(txt); f.close(); }
    function readText(f){ if(!f.exists) return ""; f.encoding="UTF-8"; f.open("r"); var s=f.read(); f.close(); return s; }
    // --- Cross-version presets -------------------------------------------------
    // AE stamps a format version into every RIFX file (.ffx / .aep). An older AE
    // refuses anything stamped newer ("created with a newer version"). Our presets
    // were authored in AE 2024 (0x5F), so on older hosts we lower that single byte
    // to the running host's marker. On AE 2024+ the bytes are left untouched.
    //   .ffx (form "FaFX") -> byte 27 | .aep (form "Egg!") -> byte 33
    //   2019 5A · 2020 5B · 2021 5C · 2022 5D · 2023 5E · 2024 5F · 2025 60
    var SK_MIN_AE = 22;                 // AE 2022 — oldest host the bundled presets survive
    // Unknown/odd version string -> behave exactly like the newest host:
    // never patch a file, never block. Failure mode must be "do nothing".
    function skHostMajor(){ var v=NaN; try{ v=parseInt(app.version,10); }catch(e){}
        if(isNaN(v) || v<=0) v=99; return v; }
    function skFormatMarker(){
        var v=skHostMajor();
        if(v>=25) return 0x60;          // 2025+ (and unknown) -> no downgrade at all
        if(v>=24) return 0x5F;          // 2024 -> equals our files' stamp -> untouched
        if(v>=23) return 0x5E;
        if(v>=22) return 0x5D;
        return 0x5F;                    // <2022 is blocked anyway; never stamp lower
    }
    // One clear message instead of half-broken effects on unsupported hosts.
    var SK_WARNED=false;
    function skHostSupported(){
        if(skHostMajor()>=SK_MIN_AE) return true;
        if(!SK_WARNED){
            SK_WARNED=true;
            alert("SaaS Kit 需要 After Effects 2022 或更高版本。\n\n"
                + "内置预设和绑定文件由较高版本的 After Effects 创建，\n"
                + "当前版本无法正确读取，继续使用会产生错误效果。\n\n"
                + "检测到：After Effects " + app.version);
        }
        return false;
    }
    // Cursor rigs and Backgrounds ship as .aep projects. Unlike presets these can NOT be
    // made backward compatible by patching bytes, so on an older host they simply fail.
    function skProjectAssetMsg(what, e){
        var v=""; try{ v=app.version; }catch(x){}
        return what + "需要由较高版本 After Effects 创建的项目文件。\n\n"
             + "当前版本仍可使用预设（玻璃、深度、计数器、擦除、文本、错落动画），\n"
             + "但无法使用" + what + "。After Effects 项目文件不向下兼容，\n"
             + "且无法自动转换。\n\n"
             + "检测到：After Effects " + v + "\n请使用 After Effects 2024 运行此功能。\n\n"
             + "(" + String(e) + ")";
    }
    function skDowngradeRIFX(bin){
        try{
            if(!bin || bin.length<40) return bin;
            if(bin.substr(0,4)!=="RIFX") return bin;          // PNG/other assets untouched
            var form=bin.substr(8,4), off=-1;
            if(form==="FaFX") off=27;                          // preset: byte-compatible 2022+
            // NOTE: .aep ("Egg!") is deliberately NOT patched. Project files really do change
            // format between releases — lowering the stamp only makes AE parse garbage
            // ("chunk in file too big"). Better a clean "newer version" message.
            if(off<0) return bin;
            var cur=bin.charCodeAt(off), tgt=skFormatMarker();
            if(cur<=tgt) return bin;                           // already old enough (no-op on AE 2024)
            return bin.substr(0,off)+String.fromCharCode(tgt)+bin.substr(off+1);
        }catch(e){ return bin; }
    }
    function writeBin(f,b64){ f.encoding="BINARY"; f.open("w"); f.write(skDowngradeRIFX(decode64(b64))); f.close(); }

    function activeComp(){ var c=app.project.activeItem; return (c && c instanceof CompItem)?c:null; }
    function findComp(name){ for(var i=1;i<=app.project.numItems;i++){ var it=app.project.item(i); if(it instanceof CompItem && it.name===name) return it; } return null; }
    function firstSelectedText(comp){ var s=comp.selectedLayers; for(var i=0;i<s.length;i++) if(s[i] instanceof TextLayer) return s[i]; return null; }
    function selectOnly(comp,layer){ for(var i=1;i<=comp.numLayers;i++) comp.layer(i).selected=false; layer.selected=true; }
    function applyPresetTo(comp,layer,pf){ selectOnly(comp,layer); try{ layer.applyPreset(pf); }catch(e){} }
    function isWS(ch){ return ch===" "||ch==="\r"||ch==="\n"||ch==="\t"; }
    function isShape(L){ return L && L.matchName==="ADBE Vector Layer"; }
    function tempFFX(b64,name){ var f=new File(Folder.temp.fsName+"/"+name); writeBin(f,b64); return f; }
    function applyFlow(prop,x1,y1,x2,y2){
        var v0=prop.keyValue(1),v1=prop.keyValue(2),t0=prop.keyTime(1),t1=prop.keyTime(2);
        var avg=(v1-v0)/(t1-t0);
        var inf1=Math.max(0.1,x1*100),spd1=y1*avg*100/inf1;
        var inf2=Math.max(0.1,(1-x2)*100),spd2=(1-y2)*avg*100/inf2;
        var end=new KeyframeEase(0,0.1);
        prop.setTemporalEaseAtKey(1,[end],[new KeyframeEase(spd1,inf1)]);
        prop.setTemporalEaseAtKey(2,[new KeyframeEase(spd2,inf2)],[end]);
    }


    // ---------- Deep Glow 2 auto-upgrade ----------------------------------------
    // The presets bake Deep Glow 1 (matchName "PEDG"). Deep Glow 2 ships as a SEPARATE
    // effect ("PEDG2") and its installer replaces v1 on most machines, so DG2 owners used
    // to get a dead "Missing: Deep Glow" placeholder. Whenever PEDG2 is installed we drop
    // it into the same slot and carry over the only two values our presets actually change
    // (Radius / Exposure). Param match names below are Deep Glow 2 v1.1.0.
    var SK_DG1="PEDG", SK_DG2="PEDG2", SK_DG2_RADIUS="PEDG2-0017", SK_DG2_EXPOSURE="PEDG2-0018";
    // Presets that carry Deep Glow 1 make AE pop a modal "references to missing effects"
    // warning when only Deep Glow 2 is installed. The swap right after replaces the effect,
    // so that warning is pure noise for those users: mute it for that single call.
    // try/finally is mandatory - a stuck suppressed state hides every later dialog.
    function skApplyPresetDG(comp,layer,pf){
        var dg=skDGAvail(), quiet=(!dg.has1 && dg.has2);
        if(quiet){ try{ app.beginSuppressDialogs(); }catch(e){ quiet=false; } }
        try{ applyPresetTo(comp,layer,pf); }
        finally{ if(quiet){ try{ app.endSuppressDialogs(false); }catch(e2){} } }
    }
    var _skDGCache=null;
    function skDGAvail(){
        if(_skDGCache) return _skDGCache;
        var r={has1:false,has2:false};
        try{ var l=app.effects;
            for(var i=0;i<l.length;i++){ var mn=String(l[i].matchName);
                if(mn===SK_DG1) r.has1=true; else if(mn===SK_DG2) r.has2=true; } }catch(e){}
        _skDGCache=r; return r;
    }
    // True for a Deep Glow 1 effect, including the placeholder AE leaves when v1 is missing.
    function skIsDG1(fx){
        var mn=""; try{ mn=String(fx.matchName); }catch(e){ return false; }
        if(mn===SK_DG1) return true;
        if(mn===SK_DG2) return false;
        var nm=""; try{ nm=String(fx.name); }catch(e2){}
        return /deep\s*glow/i.test(nm) && !/\b2\b/.test(nm);
    }
    function skDGSet(fx,match,val){ if(val===null||val===undefined) return; try{ fx.property(match).setValue(val); }catch(e){} }
    // Swap every Deep Glow 1 on this layer for Deep Glow 2. `fallback` = {radius,exposure}
    // used when the v1 instance is a placeholder and its values cannot be read.
    function skDeepGlow2(layer, fallback){
        if(!skDGAvail().has2) return 0;
        var par=null; try{ par=layer.property("ADBE Effect Parade"); }catch(e){ return 0; }
        if(!par) return 0;
        var swapped=0, guard=0;
        while(guard++ < 24){
            var idx=-1, fx=null;
            for(var i=1;i<=par.numProperties;i++){ var p=par.property(i); if(skIsDG1(p)){ idx=i; fx=p; break; } }
            if(idx<0) break;
            var rad=(fallback&&fallback.radius!==undefined)?fallback.radius:null;
            var exp=(fallback&&fallback.exposure!==undefined)?fallback.exposure:null;
            try{ var v1=fx.property("PEDG-0001").value; if(typeof v1==="number") rad=v1; }catch(e){}
            try{ var v2=fx.property("PEDG-0002").value; if(typeof v2==="number") exp=v2; }catch(e){}
            var nu=null;
            try{ nu=par.addProperty(SK_DG2); }catch(eAdd){ break; }   // cannot add -> leave v1 alone
            skDGSet(nu,SK_DG2_RADIUS,rad); skDGSet(nu,SK_DG2_EXPOSURE,exp);
            try{ nu.moveTo(idx); }catch(eMv){}                        // keep the original stack order
            var removed=false;
            try{ var old=par.property(idx+1); if(skIsDG1(old)){ old.remove(); removed=true; } }catch(e3){}
            if(!removed){ try{ for(var j=1;j<=par.numProperties;j++){ if(skIsDG1(par.property(j))){ par.property(j).remove(); removed=true; break; } } }catch(e4){} }
            if(!removed) break;                                        // never loop forever
            swapped++;
        }
        // Safety net: callers pass ensure:true where the preset is KNOWN to carry a Deep Glow.
        // If AE dropped the missing v1 effect on apply (or kept it under a name we cannot
        // recognise), add Deep Glow 2 anyway so the look never silently disappears.
        if(!swapped && fallback && fallback.ensure){
            var already=false;
            try{ for(var q=1;q<=par.numProperties;q++){ if(String(par.property(q).matchName)===SK_DG2){ already=true; break; } } }catch(e5){}
            if(!already){
                try{ var add=par.addProperty(SK_DG2);
                     skDGSet(add,SK_DG2_RADIUS,(fallback.radius!==undefined)?fallback.radius:null);
                     skDGSet(add,SK_DG2_EXPOSURE,(fallback.exposure!==undefined)?fallback.exposure:null);
                     swapped=1; }catch(e6){}
            }
        }
        return swapped;
    }
    // Same, for every layer of a comp and its precomps (Backgrounds ship Deep Glow inside .aep comps).
    function skDeepGlow2Comp(comp, depth){
        if(!skDGAvail().has2 || !comp || (depth||0)>3) return 0;
        var n=0;
        try{
            for(var i=1;i<=comp.numLayers;i++){
                var L=comp.layer(i);
                n+=skDeepGlow2(L,null);
                try{ if(L.source && (L.source instanceof CompItem)) n+=skDeepGlow2Comp(L.source,(depth||0)+1); }catch(e){}
            }
        }catch(e2){}
        return n;
    }

    function typewriter1(){ if(!skHostSupported()) return; var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var pf=tempFFX(FFX.tw1,"sk_tw1.ffx"); var sel=comp.selectedLayers.slice(0),n=0;
        app.beginUndoGroup("Typewriter 1");
        try{ for(var i=0;i<sel.length;i++) if(sel[i] instanceof TextLayer){ applyPresetTo(comp,sel[i],pf); n++; } }
        finally{ app.endUndoGroup(); } if(!n) alert("请选择一个文本图层。"); }
    function typewriter5(){ if(!skHostSupported()) return; var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var pf=tempFFX(TW5_B64,"sk_tw5.ffx"); var sel=comp.selectedLayers.slice(0),n=0;
        app.beginUndoGroup("Typewriter");
        try{ for(var i=0;i<sel.length;i++) if(sel[i] instanceof TextLayer){ applyPresetTo(comp,sel[i],pf); n++; } }
        finally{ app.endUndoGroup(); } if(!n) alert("请选择一个文本图层。"); }
    function typewriter2(){ if(!skHostSupported()) return; var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var base=firstSelectedText(comp); if(!base){ alert("请选择一个文本图层。"); return; }
        var glowP=tempFFX(FFX.glow,"sk_tw2_glow.ffx"), baseP=tempFFX(FFX.base,"sk_tw2_base.ffx");
        app.beginUndoGroup("Typewriter 2");
        try{ var glow=base.duplicate(); glow.moveBefore(base); glow.name=base.name+" glow";
        applyPresetTo(comp,base,baseP); skApplyPresetDG(comp,glow,glowP);
        skDeepGlow2(glow,{radius:500,exposure:0.07,ensure:true}); } finally{ app.endUndoGroup(); } }
    var CFG={ RISE_FRAMES:15, RISE:90, FLOW:[0.00,0.65,0.08,0.93], BLUR_FRAMES:10, BLUR_START:9, BLUR_END:0, BLUR_FLOW:[0.00,0.10,0.08,0.93] };
    function splitRise(title,offsetFrames,buildUnits){
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var src=firstSelectedText(comp); if(!src){ alert("请选择一个文本图层。"); return; }
        var str=src.property("ADBE Text Properties").property("ADBE Text Document").value.text;
        if(!str||!str.length){ alert("所选图层没有文本。"); return; }
        var units=buildUnits(str); if(!units.length){ alert("没有可拆分的内容。"); return; }
        var fd=comp.frameDuration, OFFSET=offsetFrames*fd, RISE_DUR=CFG.RISE_FRAMES*fd, BLUR_DUR=CFG.BLUR_FRAMES*fd;
        app.beginUndoGroup(title);
        try{
        for(var u=0;u<units.length;u++){
            var s=units[u][0],e=units[u][1],label=units[u][2];
            var dup=src.duplicate(); dup.name=label;
            var anim=dup.property("ADBE Text Properties").property("ADBE Text Animators").addProperty("ADBE Text Animator");
            anim.name="isolate";
            anim.property("ADBE Text Animator Properties").addProperty("ADBE Text Opacity").setValue(0);
            anim.property("ADBE Text Selectors").addProperty("ADBE Text Expressible Selector")
                .property("ADBE Text Expressible Amount").expression="(textIndex >= "+s+" && textIndex <= "+e+") ? 0 : 100;";
            var tg=dup.property("ADBE Transform Group"), posGroup=tg.property("ADBE Position"), b=posGroup.value;
            posGroup.dimensionsSeparated=true; var y=tg.property("ADBE Position_1");
            var t0=comp.time+u*OFFSET, t1=t0+RISE_DUR;
            y.setValueAtTime(t0,b[1]+CFG.RISE); y.setValueAtTime(t1,b[1]);
            applyFlow(y,CFG.FLOW[0],CFG.FLOW[1],CFG.FLOW[2],CFG.FLOW[3]);
            var fx=dup.property("ADBE Effect Parade").addProperty("ADBE Box Blur2");
            var rad=fx.property("ADBE Box Blur2-0001");
            rad.setValueAtTime(t0,CFG.BLUR_START); rad.setValueAtTime(t0+BLUR_DUR,CFG.BLUR_END);
            applyFlow(rad,CFG.BLUR_FLOW[0],CFG.BLUR_FLOW[1],CFG.BLUR_FLOW[2],CFG.BLUR_FLOW[3]);
            dup.startTime=0; dup.inPoint=t0;
        }
        src.enabled=false; } finally{ app.endUndoGroup(); }
    }
    function unitsByChar(str){ var a=[]; for(var k=0;k<str.length;k++){ var ch=str.charAt(k); if(isWS(ch)) continue; a.push([k+1,k+1,"char "+(k+1)+" '"+ch+"'"]); } return a; }
    function unitsByWord(str){ var a=[],i=0,n=str.length; while(i<n){ while(i<n&&isWS(str.charAt(i))) i++; if(i>=n) break; var s=i; while(i<n&&!isWS(str.charAt(i))) i++; var e=i-1; a.push([s+1,e+1,"word '"+str.substring(s,e+1)+"'"]); } return a; }
    function typewriter3(){ splitRise("Typewriter 3",2,unitsByChar); }
    function typewriter4(){ splitRise("Typewriter 4",3,unitsByWord); }

    var SAAS_COUNTER_B64 = "";
    var SAAS_COUNTER_EXPR = "// SaaS Counter\nvar num = effect(\"Num\")(\"Pseudo/90210-0001\");\nvar tSep = Math.round(effect(\"Num\")(\"Pseudo/90210-0002\"));\nvar dSep = Math.round(effect(\"Num\")(\"Pseudo/90210-0003\"));\nvar precise = Math.round(effect(\"Num\")(\"Pseudo/90210-0004\"));\nvar symbols = Math.round(effect(\"Num\")(\"Pseudo/90210-0005\"));\nvar financial = effect(\"Num\")(\"Pseudo/90210-0006\") == 1;\nvar fixedDigits = Math.round(effect(\"Num\")(\"Pseudo/90210-0007\"));\n\nvar wholeRaw, decimals = \"\";\nif (precise >= 1) {\n  var dec;\n  if (dSep == 1) dec = \".\";\n  else if (dSep == 2) dec = \",\";\n  else if (dSep == 3) dec = \"_\";\n  else dec = \" \";\n  var temp = Math.abs(num).toFixed(precise);\n  var partsD = temp.split(\".\");\n  wholeRaw = partsD[0];\n  decimals = dec + partsD[1];\n} else {\n  wholeRaw = Math.abs(Math.round(num)).toString();\n}\n\nif (fixedDigits > 1) {\n  var zeros = fixedDigits - wholeRaw.toString().length;\n  for (var z = 0; z < zeros; z++) { wholeRaw = \"0\" + wholeRaw; }\n}\n\nvar whole;\nif (tSep == 1) {\n  whole = wholeRaw.toString();\n} else {\n  var sep;\n  if (tSep == 2) sep = \",\";\n  else if (tSep == 3) sep = \".\";\n  else if (tSep == 4) sep = \"_\";\n  else sep = \" \";\n  whole = wholeRaw.toString().replace(/\\B(?=(\\d{3})+(?!\\d))/g, sep);\n}\n\nvar prefix = \"\", suffix = \"\";\nif (symbols == 2) { prefix = \"$\"; }\nelse if (symbols == 3) { suffix = \"%\"; }\nelse if (symbols == 4) { prefix = text.sourceText; }\nelse if (symbols == 5) { suffix = text.sourceText; }\n\nvar negStr = \"\", open = \"\", close = \"\";\nif (num < 0) {\n  if (financial) { open = \"(\"; close = \")\"; }\n  else { negStr = \"-\"; }\n}\n\nnegStr + prefix + open + whole + decimals + close + suffix";
    function numberCounter(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers.slice(0), n=0;
        var pf=tempFFX(SAAS_COUNTER_B64,"sk_saas_counter.ffx");
        app.beginUndoGroup("Number Counter");
        try{
            for(var i=0;i<sel.length;i++){ var L=sel[i]; if(!(L instanceof TextLayer)) continue;
                selectOnly(comp,L); L.applyPreset(pf);
                L.property("ADBE Text Properties").property("ADBE Text Document").expression=SAAS_COUNTER_EXPR;
                try{ var num=L.property("ADBE Effect Parade").property("Num"); var np=num.property("Pseudo/90210-0001");
                    var fd=comp.frameDuration; np.setValueAtTime(0,0); np.setValueAtTime(60*fd,1000);
                    var ez=new KeyframeEase(0,50); np.setTemporalEaseAtKey(1,[ez],[ez]); np.setTemporalEaseAtKey(2,[ez],[ez]); }catch(e){}
                n++;
            }
        }catch(err){ alert("数字计数器错误：\n"+err.toString()); }
        app.endUndoGroup();
        if(!n) alert("请选择一个文本图层。");
    }
    function carouselExpr(n,idx){ return [
        'var ctrl = thisComp.layer("Carousel");',
        'var r  = ctrl.effect("Radius")("ADBE Slider Control-0001");',
        'var sa = ctrl.effect("Start Angle")("ADBE Angle Control-0001");',
        'var tx = ctrl.effect("Tilt X")("ADBE Angle Control-0001");',
        'var ty = ctrl.effect("Tilt Y")("ADBE Angle Control-0001");',
        'var n = '+n+'; var idx = '+idx+';',
        'var ang = degreesToRadians(sa + idx*360/n);',
        'var px = r*Math.sin(ang), py = 0, pz = r*Math.cos(ang);',
        'var ax = degreesToRadians(tx);',
        'var y1 = py*Math.cos(ax) - pz*Math.sin(ax);','var z1 = py*Math.sin(ax) + pz*Math.cos(ax);','py = y1; pz = z1;',
        'var ay = degreesToRadians(ty);',
        'var x1 = px*Math.cos(ay) + pz*Math.sin(ay);','var z2 = -px*Math.sin(ay) + pz*Math.cos(ay);','px = x1; pz = z2;',
        'var c = ctrl.transform.position;','[c[0]+px, c[1]+py, c[2]+pz];' ].join("\n"); }
    // Classic 3D is the only renderer where 3D layers still accept effects,
    // blend modes and masks (C4D / Advanced 3D disable them). Carousel needs
    // 3D layers, so make sure the comp is on Classic 3D first.
    function ensureClassic3D(comp){
        try{
            var cur=""; try{ cur=comp.renderer; }catch(e){}
            if(cur==="ADBE Standard 3d") return true;
            var list=[]; try{ list=comp.renderers; }catch(e){}
            for(var i=0;i<list.length;i++){
                if(list[i]==="ADBE Standard 3d"){ comp.renderer="ADBE Standard 3d"; return true; }
            }
        }catch(e){}
        return false;
    }
    function carousel(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers.slice(0), items=[];
        for(var i=0;i<sel.length;i++) if(sel[i].name!=="Carousel") items.push(sel[i]);
        if(items.length<1){ alert("请选择用于轮播的图层。"); return; }
        app.beginUndoGroup("Carousel");
        try{
        ensureClassic3D(comp);   // keep effects usable on the 3D layers
        var nul=comp.layers.addNull(); nul.threeDLayer=true; nul.name="Carousel";
        nul.property("ADBE Transform Group").property("ADBE Position").setValue([comp.width/2,comp.height/2,0]);
        var fx=nul.property("ADBE Effect Parade");
        var e1=fx.addProperty("ADBE Slider Control"); e1.name="Radius"; e1.property("ADBE Slider Control-0001").setValue(460);
        var e2=fx.addProperty("ADBE Angle Control"); e2.name="Start Angle"; e2.property("ADBE Angle Control-0001").setValue(0);
        var e3=fx.addProperty("ADBE Angle Control"); e3.name="Tilt X"; e3.property("ADBE Angle Control-0001").setValue(0);
        var e4=fx.addProperty("ADBE Angle Control"); e4.name="Tilt Y"; e4.property("ADBE Angle Control-0001").setValue(0);
        var n=items.length;
        for(var j=0;j<n;j++){ var L=items[j]; L.threeDLayer=true;
            var pos=L.property("ADBE Transform Group").property("ADBE Position");
            try{ pos.dimensionsSeparated=false; }catch(e){}
            pos.expression=carouselExpr(n,j); }
        // keep the control with the carousel layers, not pinned to the top of the whole comp
        var topItem=items[0]; for(var t=1;t<items.length;t++){ if(items[t].index<topItem.index) topItem=items[t]; }
        try{ nul.moveBefore(topItem); }catch(e){}
        // restore a clean LAYER selection (adding sliders leaves properties selected,
        // which makes Effects & Presets double-click do nothing)
        try{
            for(var d=1;d<=comp.numLayers;d++) comp.layer(d).selected=false;
            for(var q2=0;q2<items.length;q2++) items[q2].selected=true;
        }catch(e){}
        } finally{ app.endUndoGroup(); }
    }

    // --- link a duplicate's rectangle (size/position/roundness) to the source shape ---
    function glassFindRectChain(grp, chain){
        for(var i=1;i<=grp.numProperties;i++){
            var pr=grp.property(i); var mn=""; try{ mn=pr.matchName; }catch(e){ continue; }
            if(mn==="ADBE Vector Shape - Rect") return chain.concat([pr.name]);
            if(mn==="ADBE Vector Group" || mn==="ADBE Vectors Group"){
                var sub=(mn==="ADBE Vector Group") ? pr.property("ADBE Vectors Group") : pr;
                if(sub){ var got=glassFindRectChain(sub, (mn==="ADBE Vector Group")?chain.concat([pr.name]):chain); if(got) return got; }
            }
        }
        return null;
    }
    function glassPropByChain(layer, chain){
        var node=layer.property("ADBE Root Vectors Group");
        for(var i=0;i<chain.length && node;i++){
            var nxt=node.property(chain[i]);
            if(nxt && i<chain.length-1){ var inner=nxt.property("ADBE Vectors Group"); node = inner ? inner : nxt; }
            else node = nxt;
        }
        return node;
    }
    function glassLinkRect(srcLayer, dupLayer){
        try{
            var chain=glassFindRectChain(srcLayer.property("ADBE Root Vectors Group"), []);
            if(!chain) return false;
            var dRect=glassPropByChain(dupLayer, chain); if(!dRect) return false;
            var path='thisComp.layer("'+srcLayer.name.replace(/\\/g,"\\\\").replace(/"/g,'\\"')+'")';
            for(var i=0;i<chain.length;i++){ path+='.content("'+chain[i].replace(/"/g,'\\"')+'")'; }
            var map=[["ADBE Vector Rect Size",".size"],["ADBE Vector Rect Position",".position"],["ADBE Vector Rect Roundness",".roundness"]];
            for(var m=0;m<map.length;m++){
                try{ var pr=dRect.property(map[m][0]); if(pr && pr.canSetExpression) pr.expression=path+map[m][1]+";"; }catch(e){}
            }
            return true;
        }catch(e){ return false; }
    }
    var GLASSADV_B64="";
    // ---------- Glass (shapes only) ----------
    function glass(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers, src=null;
        for(var i=0;i<sel.length;i++){ if(isShape(sel[i])){ src=sel[i]; break; } }
        if(!src){ alert("玻璃效果仅支持形状图层。请选择一个形状。"); return; }
        app.beginUndoGroup("Glass");
        try{
        var origName=src.name;
        var l2=src.duplicate();
        var l3=src.duplicate();
        var gcName="Glass Controls - "+origName;
        var gc=comp.layers.addNull(); gc.name=gcName; gc.enabled=false; gc.guideLayer=true;
        var gb=gc.property("ADBE Effect Parade").addProperty("ADBE Slider Control"); gb.name="Blur"; gb.property("ADBE Slider Control-0001").setValue(6);
        src.adjustmentLayer=true; src.name=origName+" glass base";
        var blur=src.property("ADBE Effect Parade").addProperty("ADBE Box Blur2");
        blur.property("ADBE Box Blur2-0001").expression='thisComp.layer("'+gcName+'").effect("Blur")("Slider")';
        l2.name="glass 2"; applyPresetTo(comp,l2,tempFFX(GLASS2_B64,"sk_glass2.ffx"));
        applyPresetTo(comp,l2,tempFFX(GLASSADV_B64,"sk_glass_adv.ffx"));   // Advanced Blending
        l3.name="glass 3"; applyPresetTo(comp,l3,tempFFX(GLASS3_B64,"sk_glass3.ffx"));
        l2.moveAfter(l3); src.moveAfter(l2); gc.moveBefore(l3);
        try{ l2.parent=src; l3.parent=src; l2.shy=true; l3.shy=true; comp.hideShyLayers=true; }catch(e){}
        // keep the duplicates' rectangle in sync with the base shape
        try{ glassLinkRect(src, l2); glassLinkRect(src, l3); }catch(eLR){}
        } finally{ app.endUndoGroup(); }
    }

    // ---------- Cursor ----------
    function posValueComp(layer){ var pg=layer.property("ADBE Transform Group").property("ADBE Position");
        if(pg.dimensionsSeparated){ var tg=layer.property("ADBE Transform Group"); return [tg.property("ADBE Position_0").value,tg.property("ADBE Position_1").value]; }
        var v=pg.value; return [v[0],v[1]]; }
    function scaleProp(prop,ratio){ if(!prop) return;
        try{ if(prop.numKeys>0){ for(var k=1;k<=prop.numKeys;k++){ var v=prop.keyValue(k);
                if(v instanceof Array){ var nv=[]; for(var d=0;d<v.length;d++) nv.push(v[d]*ratio); prop.setValueAtKey(k,nv); } else prop.setValueAtKey(k,v*ratio); } }
            else { var v2=prop.value; if(v2 instanceof Array){ var nv2=[]; for(var d2=0;d2<v2.length;d2++) nv2.push(v2[d2]*ratio); prop.setValue(nv2); } else prop.setValue(v2*ratio); }
        }catch(e){} }
    function scaleLayer(L,ratio){ var tg=L.property("ADBE Transform Group"); var pg=tg.property("ADBE Position");
        if(pg.dimensionsSeparated){ scaleProp(tg.property("ADBE Position_0"),ratio); scaleProp(tg.property("ADBE Position_1"),ratio); scaleProp(tg.property("ADBE Position_2"),ratio); }
        else scaleProp(pg,ratio); scaleProp(tg.property("ADBE Scale"),ratio); }
    function fitComp(inst,active){ var ratio=active.width/inst.width;
        // Scale ONLY top-level (unparented) layers: children inherit their parent's
        // transform, so scaling every layer compounded the ratio once per rig level
        // (4 levels deep -> ratio^4: a 0.5px cursor in vertical comps, a giant one in 4K).
        if(Math.abs(ratio-1)>0.001){ for(var i=1;i<=inst.numLayers;i++){ var _L=inst.layer(i); var _hasPar=false; try{ _hasPar=(_L.parent!=null); }catch(ep){} if(!_hasPar) scaleLayer(_L,ratio); } }
        inst.width=active.width; inst.height=active.height;
        try{ inst.pixelAspect=active.pixelAspect; }catch(e){} try{ inst.frameRate=active.frameRate; }catch(e){}
        return ratio; }
    function trimFirstFrame(cmp){
        var fd=cmp.frameDuration;
        for(var i=1;i<=cmp.numLayers;i++){ try{ cmp.layer(i).startTime = cmp.layer(i).startTime - fd; }catch(e){} }
        try{ cmp.duration = cmp.duration - fd; }catch(e){}
    }
    function cursorAsset(cfg){
        var dir=new Folder(Folder.userData.fsName+"/SaaSKit/assets"); if(!dir.exists) dir.create();
        var f=new File(dir.fsName+"/"+cfg.pngName); writeBin(f,cfg.png); return f;
    }
    function relinkCursor(cfg,pngFile){
        var base=cfg.pngName.replace(/\.[^\.]+$/,"");
        app.beginSuppressDialogs();
        try{
        for(var i=1;i<=app.project.numItems;i++){ var it=app.project.item(i);
            if(it instanceof FootageItem && it.name && it.name.indexOf(base)>=0){ try{ it.replace(pngFile); }catch(e){} } }
        } finally{ app.endSuppressDialogs(false); }
    }
    function caMkdirp(path){ var f=new Folder(path); if(f.exists) return f; var pp=f.parent; if(pp && !pp.exists){ caMkdirp(pp.fsName); } try{ f.create(); }catch(e){} return f; }
    function caPrePlaceCursorPng(cfg){
        // Prevent the AEGP PNGIO import dialog: put a valid PNG where the .aep footage path expects it.
        try{ writeBin(new File(Folder.temp.fsName+"/"+cfg.pngName), cfg.png); }catch(eT){}
        try{
            var data=decode64(cfg.aep);
            var pi=data.indexOf(cfg.pngName);
            if(pi>=0){
                var fpStart=data.lastIndexOf('"fullpath":"', pi);
                if(fpStart>=0){
                    var fp=data.substring(fpStart+12, pi+cfg.pngName.length);
                    fp=fp.replace(/\\\\/g,"\\");
                    var norm=fp.replace(/\\/g,"/");
                    var slash=norm.lastIndexOf("/");
                    if(slash>0){ caMkdirp(norm.substring(0,slash)); writeBin(new File(norm), cfg.png); }
                }
            }
        }catch(e){}
    }
    function ensureCursorSrc(cfg){
        var pngFile=cursorAsset(cfg);
        var ex=findComp(cfg.cache);
        if(ex){ relinkCursor(cfg,pngFile); return ex; }
        var aepFile=new File(Folder.temp.fsName+"/sk_"+cfg.cache.replace(/[^A-Za-z0-9]/g,"_")+".aep"); writeBin(aepFile,cfg.aep);
        caPrePlaceCursorPng(cfg);
        var before={}; for(var i=1;i<=app.project.numItems;i++) before[app.project.item(i).id]=true;
        try{ app.beginSuppressDialogs(); try{ app.project.importFile(new ImportOptions(aepFile)); } finally{ app.endSuppressDialogs(false); } }catch(e){ alert(skProjectAssetMsg("光标", e)); return null; }
        var newComp=null;
        for(var j=1;j<=app.project.numItems;j++){ var it=app.project.item(j); if(!before[it.id] && it instanceof CompItem) newComp=it; }
        relinkCursor(cfg,pngFile);
        if(newComp) newComp.name=cfg.cache;
        return newComp;
    }
    function getClickTime(comp){
        try{ var mp=comp.markerProperty; if(mp&&mp.numKeys>0) for(var k=1;k<=mp.numKeys;k++){ var mk=mp.keyValue(k);
            if(mk.comment&&mk.comment.toLowerCase().indexOf("click")>=0) return mp.keyTime(k); } }catch(e){}
        for(var i=1;i<=comp.numLayers;i++){ try{ var lm=comp.layer(i).property("ADBE Marker");
            if(lm&&lm.numKeys>0) for(var k2=1;k2<=lm.numKeys;k2++){ var mk2=lm.keyValue(k2);
                if(mk2.comment&&mk2.comment.toLowerCase().indexOf("click")>=0) return lm.keyTime(k2); } }catch(e2){} }
        return null;
    }
    function followKeys(root,expr){
        for(var i=1;i<=root.numProperties;i++){ var p=root.property(i);
            if(p.numProperties && p.numProperties>0){ followKeys(p,expr); }
            else { try{ if(p.numKeys>0 && p.canSetExpression) p.expression=expr; }catch(e){} } }
    }
    function attachScaleNull(comp,target,clickAbs,cursorLayer){
        var oldParent=target.parent;
        var nul=comp.layers.addNull(); nul.name=target.name+" click-scale";
        nul.parent=oldParent;
        var bpos=target.property("ADBE Transform Group").property("ADBE Position").value;
        nul.property("ADBE Transform Group").property("ADBE Position").setValue(bpos);
        target.parent=nul;
        var saved=comp.time; comp.time=clickAbs;
        applyPresetTo(comp,nul,tempFFX(SCALE_B64,"sk_scale.ffx"));
        applyPresetTo(comp,target,tempFFX(COLOR_B64,"sk_color.ffx"));
        comp.time=saved;
        if(cursorLayer){
            var IN0=cursorLayer.inPoint;
            var off='var c=thisComp.layer("'+cursorLayer.name+'"); valueAtTime(time - (c.inPoint - ('+IN0+')));';
            try{ nul.property("ADBE Transform Group").property("ADBE Scale").expression=off; }catch(e){}
            try{ followKeys(target.property("ADBE Effect Parade"), off); }catch(e){}
            try{ var _ls=target.property("ADBE Layer Styles"); if(_ls) followKeys(_ls, off); }catch(e){}
        }
        // order (top -> bottom): cursor, null, target — all directly above the button
        try{ nul.moveBefore(target); if(cursorLayer) cursorLayer.moveBefore(nul); }catch(eN){}
    }
    // Cursor precomp padding: bigger canvas so moving the cursor never shows the frame edge.
    var CURSOR_PAD = 2.0;

    function insertCursor(cfg){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers, target=null;
        for(var i=0;i<sel.length;i++){ var nm=sel[i].name; if(nm.indexOf("Cursor")!==0 && nm.indexOf("SK Cursor")!==0){ target=sel[i]; break; } }
        var srcComp=ensureCursorSrc(cfg); if(!srcComp){ return; }
        app.beginUndoGroup(cfg.label);
        try{
        var inst=srcComp.duplicate(); inst.name="Cursor Interaction";
        fitComp(inst,comp);
        if(cfg.trimFirst) trimFirstFrame(inst);
        var _oW=inst.width, _oH=inst.height;
        // AE re-centres content when the canvas grows, so the click point ends up at the
        // NEW centre -> anchor there. (No toComp/valueAtTime: those crash Advanced 3D.)
        try{ inst.width=Math.round(_oW*CURSOR_PAD); inst.height=Math.round(_oH*CURSOR_PAD); }catch(ePad){}
        try{ inst.renderer=ADV_RENDERER; }catch(e){}
        var cl=comp.layers.add(inst);
        try{ var _ap=cl.property("ADBE Transform Group").property("ADBE Anchor Point"); var _av=_ap.value;
             var _AX=inst.width/2, _AY=inst.height/2;
             _ap.setValue(_av.length>2?[_AX,_AY,0]:[_AX,_AY]); }catch(eAnc){}
        try{ cl.startTime=comp.time; }catch(e){}
        var clickRel=getClickTime(inst);
        if(target){
            var tp=posValueComp(target);
            var pc=cl.property("ADBE Effect Parade").addProperty("ADBE Point Control"); pc.name="Click Point";
            pc.property("ADBE Point Control-0001").setValue([tp[0],tp[1]]);
            var cpos=cl.property("ADBE Transform Group").property("ADBE Position"); var cv=cpos.value;
            cpos.expression=(cv.length===3)
              ? 'var p=effect("Click Point")("Point"); [p[0],p[1],0];'
              : 'effect("Click Point")("Point");';
            try{ cl.moveBefore(target); }catch(eOrd){}   // cursor sits above the button
            if(clickRel!=null) attachScaleNull(comp,target,comp.time+clickRel,cl);
        }
        } finally{ app.endUndoGroup(); }
    }

    function root(){ return new Folder(Folder.userData.fsName+"/SaaSKit/depth"); }
    function pyFolder(){ return new Folder(root().fsName+"/python"); }
    function pyExe(){ return new File(root().fsName+(($.os.indexOf("Windows")!=-1)?"/python/python.exe":"/python/bin/python3")); }
    function runnerFile(){ return new File(root().fsName+"/depth_runner.py"); }
    function modelFile(){ return new File(root().fsName+"/depth_anything_v2_vits.onnx"); }
    function versionFile(){ return new File(root().fsName+"/engine_version.txt"); }
    function launcher(){ return new File(root().fsName+(($.os.indexOf("Windows")!=-1)?"/run_depth.bat":"/run_depth.sh")); }
    function rmrf(folder){ if(!folder.exists) return; var it=folder.getFiles();
        for(var i=0;i<it.length;i++){ if(it[i] instanceof Folder) rmrf(it[i]); else it[i].remove(); } folder.remove(); }
    function versionOK(){ return versionFile().exists && readText(versionFile())===ENGINE_VERSION; }
    function modelLooksComplete(){ try{ var f=modelFile(); return f.exists && f.length>60000000; }catch(e){ return false; } }
    function libsInstalled(){ return pyExe().exists && modelLooksComplete() && versionOK(); }
    function skOsaQuote(t){ return String(t).replace(/\\/g,'\\\\').replace(/"/g,'\\"'); }
    // Open a visible Terminal window running `/bin/sh <script> [arg]` (macOS only).
    // Returns true if Terminal accepted the command, false when osascript is unavailable
    // or blocked (caller falls back to the old invisible run).
    function skRunInTerminal(scriptPath, arg){
        try{
            var shCmd='/bin/sh \\\"'+skOsaQuote(scriptPath)+'\\\"'+(arg?(' \\\"'+skOsaQuote(arg)+'\\\"'):'');
            var osa='tell application "Terminal"\n activate\n do script "'+shCmd+'"\nend tell';
            var osaFile=new File(root().fsName+'/launch.applescript');
            writeText(osaFile, osa);
            var res=system.callSystem('osascript "'+osaFile.fsName+'"');
            return String(res).indexOf('execution error')===-1;
        }catch(e){ return false; }
    }
    function writeRunnerAndLauncher(){
        writeText(runnerFile(),decode64(RUNNER_B64));
        if($.os.indexOf("Windows")!=-1){ writeText(launcher(),'@echo off\r\nsetlocal\r\nset HERE=%~dp0\r\n"%HERE%python\\python.exe" "%HERE%depth_runner.py" --model "%HERE%depth_anything_v2_vits.onnx" --job %1\r\n'); }
        else { writeText(launcher(),'#!/bin/sh\nHERE="$(cd "$(dirname "$0")" && pwd)"\n"$HERE/python/bin/python3" "$HERE/depth_runner.py" --model "$HERE/depth_anything_v2_vits.onnx" --job "$1"\n'); }
    }
    function ensureEngine(){
        if(!libsInstalled()){
            var upgrade=pyExe().exists && !versionOK();
            var ok=confirm((upgrade?"正在更新深度引擎（GPU）。":"正在下载用于创建深度图的模型。")+
                           "根据网络连接情况，可能需要约两分钟。\n\n是否继续？");
            if(!ok) return false;
            var r=root(); if(!r.exists) r.create();
            if(upgrade) rmrf(pyFolder());
            var rp=r.fsName;
            if($.os.indexOf("Windows")!=-1){
                var ps=new File(rp+"/setup.ps1");
                writeText(ps,'$ErrorActionPreference="Stop"\r\n$ProgressPreference="SilentlyContinue"\r\n$root="'+rp+'"\r\n'+
                    'Start-Transcript -Path "$root\\setup.log" -Append | Out-Null\r\n'+
                    '$py="$root\\python\\python.exe"\r\n'+
                    'if (-not (Test-Path $py)) {\r\n'+
                    '  Invoke-WebRequest -Uri "'+PY_WIN+'" -OutFile "$root\\py.tar.gz"\r\n'+
                    '  tar -xzf "$root\\py.tar.gz" -C "$root"\r\n'+
                    '  & $py -m pip install --upgrade pip\r\n'+
                    '  & $py -m pip install onnxruntime-directml opencv-python-headless numpy imageio imageio-ffmpeg\r\n'+
                    '}\r\n'+
                    '$m="$root\\depth_anything_v2_vits.onnx"\r\n'+
                    'if ((Test-Path $m) -and ((Get-Item $m).Length -lt 60000000)) { Remove-Item $m -Force }\r\n'+
                    'if (-not (Test-Path $m)) {\r\n'+
                    '  Invoke-WebRequest -Uri "'+ONNX_URL+'" -OutFile "$m.tmp"\r\n'+
                    '  Move-Item -Force "$m.tmp" $m\r\n'+
                    '}\r\n'+
                    'if (Test-Path "$root\\depth_anything_v2_vitb.onnx") { Remove-Item "$root\\depth_anything_v2_vitb.onnx" -Force }\r\n'+
                    'if ((Test-Path $py) -and (Test-Path $m) -and ((Get-Item $m).Length -ge 60000000)) { [System.IO.File]::WriteAllText("$root\\engine_version.txt","'+ENGINE_VERSION+'") }\r\n'+
                    'Stop-Transcript | Out-Null\r\n');
                system.callSystem('cmd.exe /c powershell -NoProfile -ExecutionPolicy Bypass -File "'+ps.fsName+'"');
            } else {
                var setup=new File(rp+"/setup.sh");
                writeText(setup,'#!/bin/sh\nset -e\nROOT="'+rp+'"\n{\n'+
                    'ARCH=$(uname -m)\n'+
                    'PY="$ROOT/python/bin/python3"\n'+
                    'if [ ! -f "$PY" ]; then\n'+
                    '  if [ "$ARCH" = "arm64" ]; then U="'+PY_MAC_ARM+'"; else U="'+PY_MAC_X64+'"; fi\n'+
                    '  curl -L "$U" -o "$ROOT/py.tar.gz"\n  tar -xzf "$ROOT/py.tar.gz" -C "$ROOT"\n'+
                    '  "$PY" -m pip install --upgrade pip\n'+
                    '  "$PY" -m pip install onnxruntime opencv-python-headless numpy imageio imageio-ffmpeg\n'+
                    'fi\n'+
                    'M="$ROOT/depth_anything_v2_vits.onnx"\n'+
                    'if [ -f "$M" ] && [ $(stat -f%z "$M" 2>/dev/null || echo 0) -lt 60000000 ]; then rm -f "$M"; fi\n'+
                    'if [ ! -f "$M" ]; then curl -L "'+ONNX_URL+'" -o "$M.tmp" && mv -f "$M.tmp" "$M"; fi\n'+
                    'rm -f "$ROOT/depth_anything_v2_vitb.onnx"\n'+
                    'if [ -f "$PY" ] && [ -f "$M" ] && [ $(stat -f%z "$M" 2>/dev/null || echo 0) -ge 60000000 ]; then printf %s "'+ENGINE_VERSION+'" > "$ROOT/engine_version.txt"; fi\n'+
                    'echo\necho "SaaS Kit 深度引擎：安装完成。你可以关闭此窗口，然后再次点击 After Effects 中的“深度显现”。"\n'+
                    '} 2>&1 | tee "$ROOT/setup.log"\n');
                // Visible install: open Terminal so the user sees progress instead of a frozen AE.
                // setup.log still captures everything; on osascript failure fall back to the old
                // invisible synchronous run so nothing regresses.
                if(skRunInTerminal(setup.fsName, null)){
                    alert('深度引擎正在刚打开的“终端”窗口中安装\n'+
                          '（Python + AI 模型，所需时间取决于网络连接）。\n\n'+
                          '看到“安装完成”后，请返回并再次点击“深度显现”。');
                    return false;
                }
                system.callSystem('/bin/sh "'+setup.fsName+'"');
            }
            if(pyExe().exists && modelFile().exists){ writeText(versionFile(),ENGINE_VERSION); }
            if(!libsInstalled()){ alert("安装未完成。\n文件夹："+root().fsName); return false; }
        }
        writeRunnerAndLauncher(); return true;
    }
    function findEffectByMatch(layer,match){ var par=layer.property("ADBE Effect Parade");
        for(var i=1;i<=par.numProperties;i++) if(par.property(i).matchName===match) return par.property(i); return null; }
    function buildDepthRig(comp,main,depthItem,secondB64){
        app.beginUndoGroup("Depth Reveal");
        try{
        var mid=main.duplicate(); mid.moveBefore(main); mid.name=main.name+" reveal";
        selectOnly(comp,mid); try{ mid.applyPreset(tempFFX(secondB64,"sk_second_layer.ffx")); }catch(e){}
        var depthLayer=comp.layers.add(depthItem); depthLayer.moveBefore(mid);
        depthLayer.enabled=false; depthLayer.guideLayer=true; depthLayer.name="Depth Map - "+main.name;
        var gw=findEffectByMatch(mid,"ADBE Gradient Wipe");
        if(gw){ gw.property("ADBE Gradient Wipe-0003").setValue(depthLayer.index);
            try{
              var dcName="Depth Controls - "+main.name;
              var dc=comp.layers.addNull(); dc.name=dcName; dc.enabled=false; dc.guideLayer=true; dc.moveBefore(depthLayer);
              var ds=dc.property("ADBE Effect Parade").addProperty("ADBE Slider Control"); ds.name="Softness"; ds.property("ADBE Slider Control-0001").setValue(100);
              gw.property("ADBE Gradient Wipe-0002").expression='Math.max(0, Math.min(100, thisComp.layer("'+dcName+'").effect("Softness")("Slider")))';
            }catch(e){}
        }
        try{ depthLayer.parent=main; mid.parent=main; depthLayer.shy=true; comp.hideShyLayers=true; }catch(e){}
        } finally{ app.endUndoGroup(); }
    }
    function depthOutRoot(){
        var base=null;
        try{ if(app.project.file){ base=app.project.file.parent.fsName + "/SaaS Kit Depth"; } }catch(e){}
        if(!base) base=Folder.userData.fsName + "/SaaSKit/depth_maps";
        var f=new Folder(base); if(!f.exists) f.create(); return f;
    }
    function depthReveal(secondB64){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers.slice(0), targets=[];
        for(var i=0;i<sel.length;i++){ var L=sel[i];
            if(L.source && (L.source instanceof FootageItem) && L.source.mainSource.file) targets.push(L); }
        if(targets.length===0){ alert("请选择一个或多个基础图层（照片或视频）。"); return; }
        if(!ensureEngine()) return;
        var prov="", done=0;
        for(var t=0;t<targets.length;t++){
            var main=targets[t], inFile=main.source.mainSource.file, inPath=inFile.fsName;
            var isVideo=/\.(mp4|mov|avi|mkv|m4v|webm)$/i.test(inFile.name);
            var outDir=new Folder(depthOutRoot().fsName+"/sk_depth_"+(new Date().getTime())+"_"+t); outDir.create();
            var jobFile=new File(root().fsName+"/job.txt");
            writeUTF8(jobFile, inPath+"\n"+outDir.fsName+"\n"+(INVERT_DEPTH?"1":"0")+"\n");
            var lp=launcher().fsName;
            var doneF=new File(outDir.fsName+'/done.txt');
            var ranVisible=false;
            if($.os.indexOf('Windows')===-1){
                // macOS: run in a visible Terminal window so the user sees live progress,
                // then wait for the runner's done-marker (AE stays busy, Terminal shows life).
                ranVisible=skRunInTerminal(lp, jobFile.fsName);
                if(ranVisible){
                    var waited=0, TIMEOUT=30*60*1000;
                    while(!doneF.exists && waited<TIMEOUT){ $.sleep(500); waited+=500; }
                    if(!doneF.exists){ alert('深度显现处理超时：'+main.name+'\n请检查“终端”窗口中的错误信息。'); continue; }
                }
            }
            if(!ranVisible){
                var cmd=(($.os.indexOf('Windows')!=-1)?'"'+lp+'"':'/bin/sh "'+lp+'"')+' "'+jobFile.fsName+'"';
                system.callSystem(cmd);
            }
            prov=readText(new File(outDir.fsName+"/provider.txt"));
            var logtxt=readText(new File(outDir.fsName+"/log.txt"));
            var depthItem=null;
            if(isVideo){ var firstF=new File(outDir.fsName+"/depth_00001.png");
                if(!firstF.exists){ alert("深度处理失败："+main.name+"\n计算设备："+prov+"\n\n日志：\n"+logtxt.substr(Math.max(0,logtxt.length-1200))); continue; }
                var io=new ImportOptions(firstF); io.sequence=true; depthItem=app.project.importFile(io);
            } else { var base=inFile.name.replace(/\.[^\.]+$/,"");
                var png=new File(outDir.fsName+"/"+base+"_depth.png");
                if(!png.exists){ alert("深度处理失败："+main.name+"\n计算设备："+prov+"\n\n日志：\n"+logtxt.substr(Math.max(0,logtxt.length-1200))); continue; }
                depthItem=app.project.importFile(new ImportOptions(png)); }
            buildDepthRig(comp,main,depthItem,secondB64); done++;
        }
        alert("已完成 "+done+" 个图层的深度显现。\n计算设备："+(prov||"未知"));
    }


    // ---------- Create null / solid / adjustment ----------
    function createBound(kind){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers, target=(sel.length?sel[0]:null);
        app.beginUndoGroup("Create "+kind);
        try{
        var L;
        if(kind==="null"){ L=comp.layers.addNull(); }
        else if(kind==="solid"){ L=comp.layers.addSolid([0.5,0.5,0.5],"Solid",comp.width,comp.height,comp.pixelAspect); }
        else { L=comp.layers.addSolid([1,1,1],"Adjustment",comp.width,comp.height,comp.pixelAspect); L.adjustmentLayer=true; }
        if(target){
            L.moveBefore(target);
            try{ L.startTime=target.startTime; }catch(e){}
            try{ L.inPoint=target.inPoint; }catch(e){}
            try{ L.outPoint=target.outPoint; }catch(e){}
            target.parent=L;
        } else {
            try{ L.startTime=0; L.inPoint=0; L.outPoint=comp.duration; }catch(e){}
        }
        } finally{ app.endUndoGroup(); }
    }
    function ensureSliderOn(layer,name,val){ var fx=layer.property("ADBE Effect Parade"); for(var i=1;i<=fx.numProperties;i++){ if(fx.property(i).name===name) return fx.property(i); } var e=fx.addProperty("ADBE Slider Control"); e.name=name; e.property("ADBE Slider Control-0001").setValue(val); return e; }
    function getLayerOf(p){ try{ return p.propertyGroup(p.propertyDepth); }catch(e){ var d=p; while(d&&d.parentProperty){ d=d.parentProperty; } return d; } }
    var BOUNCE_CTRL_EXPR="amp = effect(\"Bounce Amp\")(\"Slider\")/100;\nfreq = effect(\"Bounce Freq\")(\"Slider\");\ndecay = effect(\"Bounce Decay\")(\"Slider\");\nn = 0; time_max = 4;\nif (numKeys > 0){ n = nearestKey(time).index; if (key(n).time > time){ n--; } }\nif (n == 0){ t = 0; } else { t = time - key(n).time; }\nif (n > 0 && t < time_max){\nv = velocityAtTime(key(n).time - thisComp.frameDuration/10);\nvalue + v*amp*Math.sin(freq*t*2*Math.PI)/Math.exp(decay*t);\n} else { value }";
    var BOUNCE_EXPR="amp = .1;\nfreq = 2.0;\ndecay = 5.0;\nn = 0;\ntime_max = 4;\nif (numKeys > 0){\nn = nearestKey(time).index;\nif (key(n).time > time){\nn--;\n}}\nif (n == 0){ t = 0;\n}else{\nt = time - key(n).time;\n}\nif (n > 0 && t < time_max){\nv = velocityAtTime(key(n).time - thisComp.frameDuration/10);\nvalue + v*amp*Math.sin(freq*t*2*Math.PI)/Math.exp(decay*t);\n}else{value}";
    function addBounce(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var props=comp.selectedProperties, n=0;
        app.beginUndoGroup("Bounce");
        try{
        for(var i=0;i<props.length;i++){ var p=props[i];
            if(p && p.canSetExpression){ var _L=getLayerOf(p); try{ ensureSliderOn(_L,"Bounce Amp",10); ensureSliderOn(_L,"Bounce Freq",2); ensureSliderOn(_L,"Bounce Decay",5); p.expression=BOUNCE_CTRL_EXPR; n++; }catch(e){} } }
        } finally{ app.endUndoGroup(); }
        if(!n) alert("请选择带有关键帧的属性（位置、缩放等）。");
    }
    // ---------- Text Exploder ----------
    function unitsByLine(str){ var a=[],i=0,n=str.length;
        while(i<n){ while(i<n&&(str.charAt(i)==="\r"||str.charAt(i)==="\n")) i++; if(i>=n) break;
            var s=i; while(i<n&&str.charAt(i)!=="\r"&&str.charAt(i)!=="\n") i++; var e=i-1;
            a.push([s+1,e+1,"line '"+str.substring(s,Math.min(e+1,s+15))+"'"]); } return a; }
    function explodeText(buildUnits,title){
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var src=firstSelectedText(comp); if(!src){ alert("请选择一个文本图层。"); return; }
        var str=src.property("ADBE Text Properties").property("ADBE Text Document").value.text;
        if(!str||!str.length){ alert("所选图层没有文本。"); return; }
        var units=buildUnits(str); if(!units.length){ alert("没有可拆分的内容。"); return; }
        app.beginUndoGroup(title);
        try{
        for(var u=0;u<units.length;u++){ var s=units[u][0],e=units[u][1],label=units[u][2];
            var dup=src.duplicate(); dup.name=label;
            var anim=dup.property("ADBE Text Properties").property("ADBE Text Animators").addProperty("ADBE Text Animator");
            anim.name="isolate";
            anim.property("ADBE Text Animator Properties").addProperty("ADBE Text Opacity").setValue(0);
            anim.property("ADBE Text Selectors").addProperty("ADBE Text Expressible Selector")
                .property("ADBE Text Expressible Amount").expression="(textIndex >= "+s+" && textIndex <= "+e+") ? 0 : 100;";
        }
        src.enabled=false; } finally{ app.endUndoGroup(); }
    }
    function explodeLetters(){ if(!skHostSupported()) return; explodeText(unitsByChar,"Explode Letters"); }
    function explodeWords(){ if(!skHostSupported()) return; explodeText(unitsByWord,"Explode Words"); }
    function explodeLines(){ if(!skHostSupported()) return; explodeText(unitsByLine,"Explode Lines"); }


    // ================= Backgrounds (BG Gradients) =================
    var BG_B64 = "";
    // type "solid": map layerName->hex (unlisted shapes get no controller)
    // type "tritone": recolor precomp via Tritone; 2 colors => Hi/Shadows(+blend mid), 3 => Hi/Mid/Shadows
    var BG_GRADS = {
      "Gradient 1":{type:"solid", map:[["Vector 7","D6C7F9"],["Vector 6","8C5BFF"],["Vector 5","530AFF"]]},
      "Gradient 2":{type:"solid", map:[["Vector 19","7BFBFF"],["Vector 18","6035FB"]]},
      "Gradient 4":{type:"solid", map:[["Ellipse 2","92C5FF"],["Ellipse 1","145EFF"]]},
      "Gradient 5":{type:"solid", map:[["Shape Layer 4","5569FF"],["Shape Layer 2","9D55FF"],["Shape Layer 1","FFFFFF"]]},
      "Gradient 6":{type:"tritone", colors:["E1EDFF","3A86FB"]},
      "Gradient 7":{type:"tritone", colors:["AF54FC","8C3AFB"]},
      "Gradient 8":{type:"tritone", colors:["AF54FC","8C3AFB"]},
      "Star Gradient":{type:"tritone", colors:["FFFFFF","0030FF"]}
    };
    function bgDecode64(str){
      var T="ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
      var lut=[]; var i;
      for(i=0;i<256;i++) lut[i]=-1;
      for(i=0;i<64;i++) lut[T.charCodeAt(i)]=i;
      var n=str.length, out=[], part=[];
      for(i=0;i+3<n;i+=4){
        var e1=lut[str.charCodeAt(i)],e2=lut[str.charCodeAt(i+1)],e3=lut[str.charCodeAt(i+2)],e4=lut[str.charCodeAt(i+3)];
        part.push(String.fromCharCode((e1<<2)|(e2>>4)));
        if(e3>=0) part.push(String.fromCharCode(((e2&15)<<4)|(e3>>2)));
        if(e4>=0) part.push(String.fromCharCode(((e3&3)<<6)|e4));
        if(part.length>=9000){ out.push(part.join("")); part=[]; }
      }
      if(part.length) out.push(part.join(""));
      return out.join("");
    }
    function bgAssetFile(){
      var dir=new Folder(Folder.userData.fsName+"/SaaSKit/assets"); if(!dir.exists) dir.create();
      return new File(dir.fsName+"/BG_Gradients.aep");
    }
    function bgFindComp(nm){ for(var i=1;i<=app.project.numItems;i++){ var it=app.project.item(i); if(it instanceof CompItem && it.name===nm) return it; } return null; }
    function bgEnsureComp(nm){
      var c=bgFindComp(nm); if(c) return c;
      var f=bgAssetFile();
      if(!f.exists || f.length<1000){ f.encoding="BINARY"; f.open("w"); f.write(skDowngradeRIFX(bgDecode64(BG_B64))); f.close(); }
      var _dgq=false; try{ var _dg=skDGAvail(); _dgq=(!_dg.has1 && _dg.has2); }catch(eq){}
      if(_dgq){ try{ app.beginSuppressDialogs(); }catch(eq2){ _dgq=false; } }
      var _impErr=null;
      try{ app.project.importFile(new ImportOptions(f)); }catch(e){ _impErr=e; }
      finally{ if(_dgq){ try{ app.endSuppressDialogs(false); }catch(eq3){} } }
      if(_impErr){ alert(skProjectAssetMsg("背景", _impErr)); return null; }   // alert AFTER unsuppressing
      return bgFindComp(nm);
    }
    function bgHex(h){ return [parseInt(h.substr(0,2),16)/255, parseInt(h.substr(2,2),16)/255, parseInt(h.substr(4,2),16)/255, 1]; }
    function bgEsc(str){ return str.replace(/\\/g,"\\\\").replace(/"/g,'\\"'); }
    function bgLayerByName(comp,nm){ for(var i=1;i<=comp.numLayers;i++) if(comp.layer(i).name===nm) return comp.layer(i); return null; }
    function bgCollectCols(prop,out){
      if(prop.matchName==="ADBE Vector Fill Color"||prop.matchName==="ADBE Vector Stroke Color") out.push(prop);
      if(prop.numProperties){ for(var i=1;i<=prop.numProperties;i++) bgCollectCols(prop.property(i),out); }
    }
    function bgMakeCtrlNull(comp, cols){
      var nul=comp.layers.addNull();
      nul.name="Colour Control"; nul.guideLayer=true; nul.enabled=false;
      var fx=nul.property("ADBE Effect Parade");
      for(var k=0;k<cols.length;k++){
        var cc=fx.addProperty("ADBE Color Control"); cc.name="Color "+(k+1);
        cc.property("ADBE Color Control-0001").setValue(bgHex(cols[k]));
      }
      return nul;
    }
    function bgPlaceBg(comp, g){
      var bg=comp.layers.add(g); bg.moveToEnd();
      var sc=(comp.width/g.width)*100;
      bg.property("ADBE Transform Group").property("ADBE Scale").setValue([sc,sc]);
      bg.property("ADBE Transform Group").property("ADBE Position").setValue([comp.width/2,comp.height/2]);
      return bg;
    }
    function insertGradient(name){ if(!skHostSupported()) return;
      var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
      var def=BG_GRADS[name]; if(!def){ alert("未知渐变："+name); return; }
      // importFile() runs AE's own undo bookkeeping, so it must NOT happen inside our undo
      // group — that mismatch left the undo stack broken and every later edit (changing a
      // text colour, for instance) threw "Undo group mismatch".
      var g=bgEnsureComp(name);
      if(!g){ alert("未找到渐变："+name); return; }
      skDeepGlow2Comp(g,0);
      app.beginUndoGroup("Background "+name);
      try{

        if(def.type==="tritone"){
          var _ccNull=bgMakeCtrlNull(comp, def.colors);   // null with swatches in active comp
          var _bgLayer=bgPlaceBg(comp, g);                // clean gradient layer
          try{ _ccNull.moveBefore(_bgLayer); }catch(e){}  // controller right above the bg
          var hn=bgEsc(comp.name);
          var r=function(n){ return 'comp("'+hn+'").layer("Colour Control").effect("'+n+'")(1);'; };
          // Tritone hidden INSIDE the precomp, on a shy "Recolour" adjustment
          var adj=null;
          for(var ai=1; ai<=g.numLayers; ai++){ if(g.layer(ai).name==="Recolour"){ adj=g.layer(ai); break; } }
          if(!adj){
            adj=g.layers.addSolid([0,0,0],"Recolour",g.width,g.height,1,g.duration);
            adj.adjustmentLayer=true; adj.moveToBeginning();
            try{ adj.shy=true; g.hideShyLayers=true; }catch(e){}
          }
          var ep=adj.property("ADBE Effect Parade");
          var oldT=ep.property("ADBE Tritone"); if(oldT) oldT.remove();
          var tri=ep.addProperty("ADBE Tritone");
          if(def.colors.length>=3){
            tri.property(1).expression=r("Color 1");
            tri.property(2).expression=r("Color 2");
            tri.property(3).expression=r("Color 3");
          } else {
            tri.property(1).expression=r("Color 1"); // Highlights
            tri.property(3).expression=r("Color 2"); // Shadows
            tri.property(2).expression='var a='+r("Color 1")+' var b='+r("Color 2")+' (a+b)/2;';
          }
        } else {
          var cols=[]; for(var m=0;m<def.map.length;m++) cols.push(def.map[m][1]);
          var _ccNull2=bgMakeCtrlNull(comp, cols);
          var _bgLayer2=bgPlaceBg(comp, g);
          try{ _ccNull2.moveBefore(_bgLayer2); }catch(e){}
          var hn=bgEsc(comp.name);
          for(var k=0;k<def.map.length;k++){
            var ly=bgLayerByName(g,def.map[k][0]); if(!ly) continue;
            var cc=[]; bgCollectCols(ly.property("ADBE Root Vectors Group"),cc);
            var ex='comp("'+hn+'").layer("Colour Control").effect("Color '+(k+1)+'")(1);';
            for(var c=0;c<cc.length;c++) if(cc[c].canSetExpression) cc[c].expression=ex;
          }
        }
      }catch(e){ alert("错误："+e.toString()); }
      finally{ app.endUndoGroup(); }      // always close, even if something above throws
    }

    // ===== Text Reveal (expression-selector text animation) =====
    var TR_ANIM_NAME = "Text Reveal";
    var TR_CTRLS = [
        { name:"Position", type:"point",  def:[0,100] },
        { name:"Scale",    type:"slider", def:100 },
        { name:"Rotation", type:"slider", def:0 },
        { name:"Skew",     type:"slider", def:0 },
        { name:"Opacity",  type:"slider", def:0 },
        { name:"Blur",     type:"point",  def:[0,0] }
    ];
    var TR_EXPR_AMOUNT = [
        'var durF = 1.0;',
        'var delF = 0.03;',
        'var n = textTotal;',
        'var i = textIndex - 1;',
        'var t0 = inPoint + i * delF;',
        'var t = (time - t0) / Math.max(0.001, durF);',
        'if (t < 0) t = 0;',
        'if (t > 1) t = 1;',
        'var e = (t >= 1) ? 1 : ((t <= 0) ? 0 : (1 - Math.pow(2, -10 * t)));',
        '(1 - e) * 100;'
    ].join('\n');
    var TR_EXPR_POS = 'var p=effect("Position")("Point"); [p[0], p[1], 0];';
    var TR_EXPR_SCL = 'var s=effect("Scale")("Slider"); [s, s, 100];';
    var TR_EXPR_ROT = 'effect("Rotation")("Slider");';
    var TR_EXPR_SKW = 'effect("Skew")("Slider");';
    var TR_EXPR_OPA = 'effect("Opacity")("Slider");';
    var TR_EXPR_BLR = 'effect("Blur")("Point");';

    function trSelectedText(comp){ var s=comp.selectedLayers,out=[]; for(var i=0;i<s.length;i++) if(s[i] instanceof TextLayer) out.push(s[i]); return out; }
    function trFindAnimator(layer){ return layer.property("ADBE Text Properties").property("ADBE Text Animators").property(TR_ANIM_NAME); }
    function trAddExpr(props,match,expr){ try{ var pr=props.addProperty(match); pr.expression=expr; return pr; }catch(e){ return null; } }

    function trSetupLayer(layer, rangeType){
        var oldA=trFindAnimator(layer); if(oldA) oldA.remove();
        var fx=layer.property("ADBE Effect Parade");
        for(var c=0;c<TR_CTRLS.length;c++){ var od=fx.property(TR_CTRLS[c].name); if(od) od.remove(); }
        for(var k=0;k<TR_CTRLS.length;k++){
            var ctl=TR_CTRLS[k];
            var e=fx.addProperty(ctl.type==="point"?"ADBE Point Control":"ADBE Slider Control");
            e.name=ctl.name; try{ e.property(1).setValue(ctl.def); }catch(se){}
        }
        var animators=layer.property("ADBE Text Properties").property("ADBE Text Animators");
        var anim=animators.addProperty("ADBE Text Animator"); anim.name=TR_ANIM_NAME;
        var props=anim.property("ADBE Text Animator Properties");
        trAddExpr(props,"ADBE Text Position 3D",TR_EXPR_POS);
        trAddExpr(props,"ADBE Text Scale 3D",TR_EXPR_SCL);
        trAddExpr(props,"ADBE Text Rotation",TR_EXPR_ROT);
        trAddExpr(props,"ADBE Text Skew",TR_EXPR_SKW);
        trAddExpr(props,"ADBE Text Opacity",TR_EXPR_OPA);
        trAddExpr(props,"ADBE Text Blur",TR_EXPR_BLR);
        var sels=anim.property("ADBE Text Selectors");
        while(sels.numProperties>0){ sels.property(1).remove(); }
        var xsel=sels.addProperty("ADBE Text Expressible Selector");
        try{ xsel.property("ADBE Text Range Type2").setValue(rangeType); }catch(e1){}
        var amt=null; try{ amt=xsel.property("ADBE Text Expressible Amount"); }catch(e2){}
        if(!amt){ try{ amt=xsel.property("Amount"); }catch(e3){} }
        if(amt){ amt.expression=TR_EXPR_AMOUNT; }
        try{ layer.property("ADBE Text Properties").property("ADBE Text More Options").property("ADBE Text Anchor Point Option").setValue(1); }catch(e4){}
        try{ layer.motionBlur=true; }catch(e5){}
    }
    function trSetupAll(rangeType){
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var layers=trSelectedText(comp); if(!layers.length){ alert("请选择一个文本图层。"); return; }
        app.beginUndoGroup("Text Reveal");
        try{ try{ comp.motionBlur=true; }catch(mb){} for(var i=0;i<layers.length;i++) trSetupLayer(layers[i], rangeType); }
        catch(err){ alert("文本显现错误：\n"+err.toString()+(err.line?("\n（行号 "+err.line+")"):"")); }
        app.endUndoGroup();
    }
    function caCharacters(){ if(!skHostSupported()) return; trSetupAll(1); }
    function caWords(){ if(!skHostSupported()) return; trSetupAll(3); }


    // ===== UI Stagger (FX) =====
    var US_FFX="";
    var US_POS_T="var stgF=ctl.effect(\"Stagger Frames\")(\"Slider\");\nvar baked=__BAKED__;\nvar extra=(stgF-baked)*__RANK__*thisComp.frameDuration;\nvar p=1; try{ p=clamp(thisLayer.effect(\"Stagger Curve\")(\"Slider\").valueAtTime(time-extra),0,100)/100; }catch(e){}\nvar off=ctl.effect(\"Position\")(\"Point\");\nvar dx=off[0]*(1-p), dy=off[1]*(1-p);\n(value.length===3) ? value+[dx,dy,0] : value+[dx,dy];";
    var US_SCL_T="var stgF=ctl.effect(\"Stagger Frames\")(\"Slider\");\nvar baked=__BAKED__;\nvar extra=(stgF-baked)*__RANK__*thisComp.frameDuration;\nvar p=1; try{ p=clamp(thisLayer.effect(\"Stagger Curve\")(\"Slider\").valueAtTime(time-extra),0,100)/100; }catch(e){}\nvar s0=ctl.effect(\"Scale\")(\"Slider\");\nvar m=(s0 + p*(100-s0))/100;\nvalue*m;";
    var US_OPA_T="var stgF=ctl.effect(\"Stagger Frames\")(\"Slider\");\nvar baked=__BAKED__;\nvar extra=(stgF-baked)*__RANK__*thisComp.frameDuration;\nvar o0=ctl.effect(\"Opacity From\")(\"Slider\");\nvar v=thisProperty.valueAtTime(time-extra);\nvar t=clamp(v,0,100)/100;\no0 + t*(__BASEOPA__-o0);";
    var US_CTRL_BASE="UI Stagger Controls", US_CURVE="Stagger Curve";
    var US_CURVE_FRAMES=30, US_OPA_FRAMES=5, US_BASE_STEP=2;
    function usEsc(s){ return s.replace(/\\/g,"\\\\").replace(/"/g,'\\"'); }
    function usUnique(comp,base){ var n=base,k=2,u={}; for(var i=1;i<=comp.numLayers;i++)u[comp.layer(i).name]=1; while(u[n])n=base+" "+(k++); return n; }
    function usVecLen(a,b){ var s=0,n=Math.min(a.length,b.length); for(var i=0;i<n;i++){ var d=a[i]-b[i]; s+=d*d; } return Math.sqrt(s); }
    function usFill(t,rank,baseOpa,baked){ return t.replace(/__RANK__/g,String(rank)).replace(/__BASEOPA__/g,String(baseOpa)).replace(/__BAKED__/g,String(baked)); }
    function usHarvest(comp, L, pf){
        var fd=comp.frameDuration;
        var tg=L.property("ADBE Transform Group");
        var pos=tg.property("ADBE Position");
        var basePos=null; try{ basePos=pos.value; }catch(e){}
        selectOnly(comp,L);
        L.applyPreset(pf);
        pos=L.property("ADBE Transform Group").property("ADBE Position");
        var info={ keys:[] };
        try{
            var n=pos.numKeys;
            var vFirst=pos.keyValue(1), vLast=pos.keyValue(n);
            var amp=usVecLen(vFirst,vLast); if(amp<0.001) amp=1;
            var t1=pos.keyTime(1), tN=pos.keyTime(n);
            var origDur=Math.max(0.0001, tN-t1);
            var newDur=US_CURVE_FRAMES*fd, spdFix=origDur/newDur;
            for(var k=1;k<=n;k++){
                var ie=pos.keyInTemporalEase(k)[0], oe=pos.keyOutTemporalEase(k)[0];
                var frac=(pos.keyTime(k)-t1)/origDur;
                info.keys.push({ t:L.inPoint+frac*newDur,
                    inf:[Math.max(0.1,ie.influence),Math.max(0.1,oe.influence)],
                    spd:[ie.speed*100/amp*spdFix, oe.speed*100/amp*spdFix] });
            }
            while(pos.numKeys>0) pos.removeKey(1);
            if(basePos!=null) pos.setValue(basePos);
        }catch(e){}
        try{
            var op=L.property("ADBE Transform Group").property("ADBE Opacity");
            if(op.numKeys>0){
                var vA=op.keyValue(1), vB=op.keyValue(op.numKeys);
                while(op.numKeys>0) op.removeKey(1);
                op.setValueAtTime(L.inPoint, vA);
                op.setValueAtTime(L.inPoint+US_OPA_FRAMES*fd, vB);
                try{ op.setInterpolationTypeAtKey(1, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR);
                     op.setInterpolationTypeAtKey(2, KeyframeInterpolationType.LINEAR, KeyframeInterpolationType.LINEAR); }catch(eL){}
            }
        }catch(eO){}
        return info;
    }
    function usAddCurve(L, info){
        var fx=L.property("ADBE Effect Parade");
        var old=fx.property(US_CURVE); if(old) old.remove();
        var s=fx.addProperty("ADBE Slider Control"); s.name=US_CURVE;
        var sl=fx.property(US_CURVE).property(1);
        var n=info.keys.length; if(n<2) return;
        for(var k=0;k<n;k++) sl.setValueAtTime(info.keys[k].t, (k/(n-1))*100);
        for(var k2=0;k2<n;k2++){
            try{ var kk=info.keys[k2];
                sl.setTemporalEaseAtKey(k2+1,[new KeyframeEase(kk.spd[0],kk.inf[0])],[new KeyframeEase(kk.spd[1],kk.inf[1])]); }catch(e){}
        }
    }
    function usFind(comp, ctrlName){
        var out=[];
        for(var i=1;i<=comp.numLayers;i++){
            var L=comp.layer(i);
            try{
                var fx=L.property("ADBE Effect Parade"); if(!fx || !fx.property(US_CURVE)) continue;
                var ex=""; try{ ex=L.property("ADBE Transform Group").property("ADBE Scale").expression; }catch(e){}
                if(ex && ex.indexOf('"'+ctrlName+'"')>=0) out.push(L);
            }catch(e){}
        }
        return out;
    }
    function usRebake(comp, ctrl){
        var fxc=ctrl.property("ADBE Effect Parade");
        var stg=US_BASE_STEP; try{ stg=Math.max(0, Math.round(fxc.property("Stagger Frames").property(1).value)); }catch(e){}
        var fd=comp.frameDuration;
        var Ls=usFind(comp, ctrl.name); if(!Ls.length) return false;
        Ls.sort(function(a,b){ return a.inPoint-b.inPoint || b.index-a.index; });
        var base=Ls[0].inPoint;
        for(var i=0;i<Ls.length;i++){
            var tgt=base+i*stg*fd;
            try{ Ls[i].startTime += (tgt-Ls[i].inPoint); }catch(e){}
            var tg=Ls[i].property("ADBE Transform Group");
            var names=["ADBE Position","ADBE Scale","ADBE Opacity"];
            for(var q=0;q<names.length;q++){
                try{ var pr=tg.property(names[q]);
                     if(pr && pr.expression) pr.expression=pr.expression.replace(/var baked=[-\d.]+;/, "var baked="+stg+";"); }catch(e){}
            }
        }
        return true;
    }
    function uiStagger(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers.slice(0);
        if(sel.length===1 && sel[0].name.indexOf(US_CTRL_BASE)===0){
            app.beginUndoGroup("UI Stagger — re-bake");
            try{ if(!usRebake(comp, sel[0])) alert("此控制器未找到需要错落处理的图层。"); }
            catch(e){ alert("重新生成失败：\n"+e.toString()); }
            app.endUndoGroup(); return;
        }
        if(!sel.length){ alert("请选择要应用错落动画的图层。"); return; }
        app.beginUndoGroup("UI Stagger");
        try{
            var fd=comp.frameDuration;
            var pf=tempFFX(US_FFX,"sk_ui_stagger.ffx");
            var Ls=sel.slice(0); Ls.sort(function(a,b){ return b.index-a.index; });
            var baseIn=Ls[0].inPoint; for(var q=1;q<Ls.length;q++) if(Ls[q].inPoint<baseIn) baseIn=Ls[q].inPoint;
            var name=usUnique(comp, US_CTRL_BASE);
            var ctrl=comp.layers.addNull(comp.duration); ctrl.name=name;
            var cfx=ctrl.property("ADBE Effect Parade");
            function sl(nm,val){ var s=cfx.addProperty("ADBE Slider Control"); s.name=nm; try{ s.property(1).setValue(val);}catch(e){} return s; }
            sl("Stagger Frames",US_BASE_STEP);
            cfx.addProperty("ADBE Point Control").name="Position";
            sl("Scale",100);
            sl("Opacity From",0);
            var CTL='var ctl=thisComp.layer("'+usEsc(name)+'");\n';
            var savedT=comp.time;
            for(var i=0;i<Ls.length;i++){
                var L=Ls[i];
                var tgt=baseIn+i*US_BASE_STEP*fd;
                try{ L.startTime += (tgt-L.inPoint); }catch(e){}
                comp.time=tgt;
                var baseOpa=100; try{ baseOpa=L.property("ADBE Transform Group").property("ADBE Opacity").value; }catch(e){}
                var info=usHarvest(comp, L, pf);
                usAddCurve(L, info);
                var tg=L.property("ADBE Transform Group");
                try{ var pg=tg.property("ADBE Position"); if(!pg.dimensionsSeparated) pg.expression=CTL+usFill(US_POS_T,i,baseOpa,US_BASE_STEP); }catch(e1){}
                try{ tg.property("ADBE Scale").expression=CTL+usFill(US_SCL_T,i,baseOpa,US_BASE_STEP); }catch(e2){}
                try{ tg.property("ADBE Opacity").expression=CTL+usFill(US_OPA_T,i,baseOpa,US_BASE_STEP); }catch(e3){}
            }
            comp.time=savedT;
            try{ cfx.property("Position").property(1).setValue([0,50]); }catch(e){}
            var top=Ls[0]; for(var t2=0;t2<Ls.length;t2++) if(Ls[t2].index<top.index) top=Ls[t2];
            try{ ctrl.moveBefore(top); }catch(eM){}
        }catch(err){ alert("UI 错落动画错误：\n"+err.toString()+(err.line?("\n（行号 "+err.line+")"):"")); }
        app.endUndoGroup();
    }

    // ===== Proximity Hover (FX) =====
    var PX_SCALE="var radius=Math.max(1, ctl.effect(\"Radius\")(\"Slider\"));\nvar myC=thisLayer.toComp(thisLayer.anchorPoint);\nvar tC=ctl.toComp(ctl.anchorPoint);\nvar d=length([myC[0],myC[1]],[tC[0],tC[1]]);\nvar f=ease(d, 0, radius, 1, 0);\nvar boost=ctl.effect(\"Scale Boost\")(\"Slider\");\nvalue*(1 + f*boost/100);";
    var PX_OPA="var radius=Math.max(1, ctl.effect(\"Radius\")(\"Slider\"));\nvar myC=thisLayer.toComp(thisLayer.anchorPoint);\nvar tC=ctl.toComp(ctl.anchorPoint);\nvar d=length([myC[0],myC[1]],[tC[0],tC[1]]);\nvar f=ease(d, 0, radius, 1, 0);\nvar rest=ctl.effect(\"Rest Opacity\")(\"Slider\");\nif(rest>=100){ value; } else { value*(rest + f*(100-rest))/100; }";
    var PX_POS="var radius=Math.max(1, ctl.effect(\"Radius\")(\"Slider\"));\nvar myC=thisLayer.toComp(thisLayer.anchorPoint);\nvar tC=ctl.toComp(ctl.anchorPoint);\nvar d=length([myC[0],myC[1]],[tC[0],tC[1]]);\nvar f=ease(d, 0, radius, 1, 0);\nvar att=ctl.effect(\"Attract\")(\"Slider\");\nif(att==0){ value; } else {\n  var dv=[tC[0]-myC[0], tC[1]-myC[1]];\n  var len=Math.max(1, Math.sqrt(dv[0]*dv[0]+dv[1]*dv[1]));\n  var mv=[dv[0]/len*f*att, dv[1]/len*f*att];\n  if(hasParent){ try{ mv=parent.fromCompVect(mv); }catch(e){} }\n  (value.length===3) ? value+[mv[0],mv[1],0] : value+mv;\n}";
    function pxEsc(s){ return s.replace(/\\/g,"\\\\").replace(/"/g,'\\"'); }
    function pxUnique(comp, base){
        var n=base, k=2, used={};
        for(var i=1;i<=comp.numLayers;i++) used[comp.layer(i).name]=1;
        while(used[n]) n=base+" "+(k++);
        return n;
    }
    function proximityHover(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers.slice(0);
        if(!sel.length){ alert("请选择需要响应交互的图层。"); return; }
        app.beginUndoGroup("Proximity Hover");
        try{
            var name=pxUnique(comp,"Proximity Target");
            var ctrl=comp.layers.addNull(comp.duration); ctrl.name=name;
            var fx=ctrl.property("ADBE Effect Parade");
            function sl(nm,val){ var s=fx.addProperty("ADBE Slider Control"); s.name=nm; try{ s.property(1).setValue(val);}catch(e){} return s; }
            sl("Radius",400); sl("Scale Boost",30); sl("Attract",0); sl("Rest Opacity",100);
            var CTL='var ctl=thisComp.layer("'+pxEsc(name)+'");\n';
            for(var i=0;i<sel.length;i++){
                var L=sel[i]; if(L===ctrl) continue;
                var tg=L.property("ADBE Transform Group");
                try{ tg.property("ADBE Scale").expression=CTL+PX_SCALE; }catch(e1){}
                try{ tg.property("ADBE Opacity").expression=CTL+PX_OPA; }catch(e2){}
                try{ var pg=tg.property("ADBE Position"); if(!pg.dimensionsSeparated) pg.expression=CTL+PX_POS; }catch(e3){}
            }
            var top=sel[0]; for(var t=1;t<sel.length;t++) if(sel[t].index<top.index) top=sel[t];
            try{ ctrl.moveBefore(top); }catch(eM){}
            try{ ctrl.property("ADBE Transform Group").property("ADBE Position").setValue([comp.width/2,comp.height/2]); }catch(eC){}
        }catch(err){ alert("邻近悬停错误：\n"+err.toString()+(err.line?("\n（行号 "+err.line+")"):"")); }
        app.endUndoGroup();
    }

    // ===== Gradient Wipe (FX) =====
    var GW_CTRL="Gradient Wipe Controls", GW_NAME="Gradient Wipe", GW_FRAMES=30;
    var GW_RSTART="var a=ctl.effect(\"Angle\")(\"Angle\")*Math.PI/180;\nvar TGT=thisComp.layer(TNAME);\nvar r=TGT.sourceRectAtTime(time,false);\nvar q0=TGT.toComp([r.left,r.top]), q1=TGT.toComp([r.left+r.width,r.top]),\n    q2=TGT.toComp([r.left+r.width,r.top+r.height]), q3=TGT.toComp([r.left,r.top+r.height]);\nvar Q=[q0,q1,q2,q3];\nvar cx=(q0[0]+q1[0]+q2[0]+q3[0])/4, cy=(q0[1]+q1[1]+q2[1]+q3[1])/4;\nvar dx=Math.sin(a), dy=-Math.cos(a);\nvar t=0;\nfor(var i=0;i<4;i++){ var p=Math.abs((Q[i][0]-cx)*dx + (Q[i][1]-cy)*dy); if(p>t) t=p; }\nt+=50;\nthisLayer.fromComp([cx-dx*t, cy-dy*t]);";
    var GW_REND="var a=ctl.effect(\"Angle\")(\"Angle\")*Math.PI/180;\nvar TGT=thisComp.layer(TNAME);\nvar r=TGT.sourceRectAtTime(time,false);\nvar q0=TGT.toComp([r.left,r.top]), q1=TGT.toComp([r.left+r.width,r.top]),\n    q2=TGT.toComp([r.left+r.width,r.top+r.height]), q3=TGT.toComp([r.left,r.top+r.height]);\nvar Q=[q0,q1,q2,q3];\nvar cx=(q0[0]+q1[0]+q2[0]+q3[0])/4, cy=(q0[1]+q1[1]+q2[1]+q3[1])/4;\nvar dx=Math.sin(a), dy=-Math.cos(a);\nvar t=0;\nfor(var i=0;i<4;i++){ var p=Math.abs((Q[i][0]-cx)*dx + (Q[i][1]-cy)*dy); if(p>t) t=p; }\nt+=50;\nthisLayer.fromComp([cx+dx*t, cy+dy*t]);";
    var GW_MASK="var a=ctl.effect(\"Angle\")(\"Angle\")*Math.PI/180;\nvar prog=ctl.effect(\"Progress\")(\"Slider\")/100; if(prog<0)prog=0; if(prog>1)prog=1;\nvar TGT=thisComp.layer(TNAME);\nvar r=TGT.sourceRectAtTime(time,false);\nvar q0=TGT.toComp([r.left,r.top]), q1=TGT.toComp([r.left+r.width,r.top]),\n    q2=TGT.toComp([r.left+r.width,r.top+r.height]), q3=TGT.toComp([r.left,r.top+r.height]);\nvar Q=[q0,q1,q2,q3];\nvar cx=(q0[0]+q1[0]+q2[0]+q3[0])/4, cy=(q0[1]+q1[1]+q2[1]+q3[1])/4;\nvar dx=Math.sin(a), dy=-Math.cos(a);\nvar M=400;\nvar minx=1e12,maxx=-1e12,miny=1e12,maxy=-1e12;\nfor(var i=0;i<4;i++){ if(Q[i][0]<minx)minx=Q[i][0]; if(Q[i][0]>maxx)maxx=Q[i][0];\n                      if(Q[i][1]<miny)miny=Q[i][1]; if(Q[i][1]>maxy)maxy=Q[i][1]; }\nminx-=M; miny-=M; maxx+=M; maxy+=M;\nvar C=[[minx,miny],[maxx,miny],[maxx,maxy],[minx,maxy]];\nvar mn=1e12, mx=-1e12, j;\nfor(j=0;j<4;j++){ var p=C[j][0]*dx + C[j][1]*dy; if(p<mn)mn=p; if(p>mx)mx=p; }\nvar line = mn + (mx-mn)*prog;\nvar out=[];\nfor(j=0;j<4;j++){\n  var A=C[j], Bp=C[(j+1)%4];\n  var pa=A[0]*dx+A[1]*dy-line, pb=Bp[0]*dx+Bp[1]*dy-line;\n  if(pa<=0) out.push(thisLayer.fromComp(A));\n  if((pa<0&&pb>0)||(pa>0&&pb<0)){ var tt=pa/(pa-pb); out.push(thisLayer.fromComp([A[0]+tt*(Bp[0]-A[0]), A[1]+tt*(Bp[1]-A[1])])); }\n}\nif(out.length<3){ var z=thisLayer.fromComp([minx,miny]); createPath([z,z,z],[],[],true); } else createPath(out,[],[],true);";
    function gwEsc(s){ return s.replace(/\\/g,"\\\\").replace(/"/g,'\\"'); }
    function gwBuild(comp, src){
        var TN='var TNAME="'+gwEsc(src.name)+'";\n';
        var CTL='var ctl=thisComp.layer("'+GW_CTRL+'");\n';
        var HEAD=CTL+TN;
        var dup=src.duplicate(); dup.moveBefore(src); dup.name=src.name+" (wipe matte)";
        var sol=comp.layers.addSolid([1,1,1], GW_NAME, comp.width, comp.height, comp.pixelAspect, comp.duration);
        // Stack (top -> bottom): controller / shape matte / Gradient Wipe solid / base.
        // In AE <=2022 the track matte is ALWAYS the layer directly ABOVE, so the matte
        // must sit on top of the solid. 2023+ takes the layer reference either way.
        sol.moveBefore(src);
        var ramp=sol.property("ADBE Effect Parade").addProperty("ADBE Ramp");
        var ctrl=comp.layers.addNull(comp.duration); ctrl.name=GW_CTRL;
        var fx=ctrl.property("ADBE Effect Parade");
        var prog=fx.addProperty("ADBE Slider Control"); prog.name="Progress"; try{ prog.property(1).setValue(0);}catch(e){}
        var ang=fx.addProperty("ADBE Angle Control"); ang.name="Angle"; try{ ang.property(1).setValue(90);}catch(e){}
        var c1=fx.addProperty("ADBE Color Control"); c1.name="Color 1"; try{ c1.property(1).setValue([1,1,1,1]);}catch(e){}
        var c2=fx.addProperty("ADBE Color Control"); c2.name="Color 2"; try{ c2.property(1).setValue([0.745098,0.062745,1,1]);}catch(e){}
        try{ var ps=fx.property("Progress").property(1); var fd=comp.frameDuration;
             ps.setValueAtTime(0,0); ps.setValueAtTime(GW_FRAMES*fd,100);
             var ez=new KeyframeEase(0,40); ps.setTemporalEaseAtKey(1,[ez],[ez]); ps.setTemporalEaseAtKey(2,[ez],[ez]); }catch(e){}
        ctrl.moveBefore(dup);
        try{ ramp.property("ADBE Ramp-0001").expression=HEAD+GW_RSTART; }catch(e){}
        try{ ramp.property("ADBE Ramp-0003").expression=HEAD+GW_REND;   }catch(e){}
        try{ ramp.property("ADBE Ramp-0002").expression=CTL+'ctl.effect("Color 1")("Color");'; }catch(e){}
        try{ ramp.property("ADBE Ramp-0004").expression=CTL+'ctl.effect("Color 2")("Color");'; }catch(e){}
        try{ ramp.property("ADBE Ramp-0007").setValue(0); }catch(e){}
        try{ var mk=sol.property("ADBE Mask Parade").addProperty("ADBE Mask Atom"); mk.name="Wipe";
             try{ mk.maskMode=MaskMode.ADD; }catch(e){}
             try{ mk.inverted=true; }catch(eI){}
             mk.property("ADBE Mask Shape").expression=HEAD+GW_MASK;
             try{ mk.property("ADBE Mask Feather").setValue([300,300]); }catch(eF){} }catch(eMK){}
        try{ sol.setTrackMatte(dup, TrackMatteType.ALPHA); }
        catch(e){ try{ sol.trackMatteType=TrackMatteType.ALPHA; }catch(e2){} }
        // Legacy AE (<=2022) does NOT hide the matte source when the matte is set by script,
        // so the duplicate would render on top and the matte looks "broken". 2023+ ignores
        // this switch for matte layers, so turning it off is safe on every version.
        try{ dup.enabled=false; }catch(eEn){}
        try{ sol.parent=src; dup.parent=src; }catch(eP){}
        try{ sol.shy=true; dup.shy=true; comp.hideShyLayers=true; }catch(eS){}
    }
    function gradientWipe(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var sel=comp.selectedLayers.slice(0);
        if(!sel.length){ alert("请选择一个图层。"); return; }
        app.beginUndoGroup("Gradient Wipe");
        try{ for(var i=0;i<sel.length;i++) gwBuild(comp, sel[i]); }
        catch(err){ alert("渐变擦除错误：\n"+err.toString()+(err.line?("\n（行号 "+err.line+")"):"")); }
        app.endUndoGroup();
    }

    // ===== Wipe Reveal 1 (FX) =====
    var WIPE_MOSTURB_B64 = "";
    var WIPE_GRADGLOW_B64 = "";
    var WIPE_ANIM_FRAMES = 40;
    var WIPE_MATTE_BODY = [
        'var W = thisLayer.width, H = thisLayer.height;',
        'var L=0, T=0, R=W, B=H, cx=W/2, cy=H/2;',
        'var prog = ctl.effect("Wipe")("Slider")/100; if(prog<0)prog=0; if(prog>1)prog=1;',
        'var radial = 0; try{ radial = ctl.effect("Radial")("Checkbox"); }catch(e){}',
        'var deg = 90; try{ deg = ctl.effect("Direction")("Angle"); }catch(e2){}',
        'if(radial==1){',
        '  var maxR = Math.sqrt((W/2)*(W/2)+(H/2)*(H/2));',
        '  var rad = maxR*prog, n=48, pts=[];',
        '  for(var i=0;i<n;i++){ var a=(i/n)*Math.PI*2; pts.push([cx+rad*Math.cos(a), cy+rad*Math.sin(a)]); }',
        '  createPath(pts,[],[],true);',
        '} else {',
        '  var th = degreesToRadians(deg);',
        '  var dx = Math.sin(th), dy = -Math.cos(th);',
        '  var C = [[L,T],[R,T],[R,B],[L,B]];',
        '  var mn=999999, mx=-999999, j;',
        '  for(j=0;j<4;j++){ var pj=C[j][0]*dx + C[j][1]*dy; if(pj<mn)mn=pj; if(pj>mx)mx=pj; }',
        '  var line = mn + (mx-mn)*prog;',
        '  var out=[];',
        '  for(j=0;j<4;j++){',
        '    var A=C[j], Bp=C[(j+1)%4];',
        '    var pa=A[0]*dx+A[1]*dy - line, pb=Bp[0]*dx+Bp[1]*dy - line;',
        '    if(pa<=0){ out.push(A); }',
        '    if((pa<0&&pb>0)||(pa>0&&pb<0)){ var t=pa/(pa-pb); out.push([A[0]+t*(Bp[0]-A[0]), A[1]+t*(Bp[1]-A[1])]); }',
        '  }',
        '  if(out.length<3){ createPath([[L,T],[L,T],[L,T]],[],[],true); } else { createPath(out,[],[],true); }',
        '}'
    ].join('\n');
    var WIPE_GLOW_BODY = [
        'var K = 6;',
        'var W = thisLayer.width, H = thisLayer.height;',
        'var L=0, T=0, R=W, B=H, cx=W/2, cy=H/2;',
        'var prog = ctl.effect("Wipe")("Slider").valueAtTime(time - K*thisComp.frameDuration)/100; if(prog<0)prog=0; if(prog>1)prog=1;',
        'var radial = 0; try{ radial = ctl.effect("Radial")("Checkbox"); }catch(e){}',
        'var deg = 90; try{ deg = ctl.effect("Direction")("Angle"); }catch(e2){}',
        'if(radial==1){',
        '  var maxR = Math.sqrt((W/2)*(W/2)+(H/2)*(H/2));',
        '  var rad = maxR*prog, n=48, pts=[];',
        '  for(var i=0;i<n;i++){ var a=(i/n)*Math.PI*2; pts.push([cx+rad*Math.cos(a), cy+rad*Math.sin(a)]); }',
        '  createPath(pts,[],[],true);',
        '} else {',
        '  var th = degreesToRadians(deg);',
        '  var dx = Math.sin(th), dy = -Math.cos(th);',
        '  var C = [[L,T],[R,T],[R,B],[L,B]];',
        '  var mn=999999, mx=-999999, j;',
        '  for(j=0;j<4;j++){ var pj=C[j][0]*dx + C[j][1]*dy; if(pj<mn)mn=pj; if(pj>mx)mx=pj; }',
        '  var line = mn + (mx-mn)*prog;',
        '  var out=[];',
        '  for(j=0;j<4;j++){',
        '    var A=C[j], Bp=C[(j+1)%4];',
        '    var pa=A[0]*dx+A[1]*dy - line, pb=Bp[0]*dx+Bp[1]*dy - line;',
        '    if(pa<=0){ out.push(A); }',
        '    if((pa<0&&pb>0)||(pa>0&&pb<0)){ var t=pa/(pa-pb); out.push([A[0]+t*(Bp[0]-A[0]), A[1]+t*(Bp[1]-A[1])]); }',
        '  }',
        '  if(out.length<3){ createPath([[L,T],[L,T],[L,T]],[],[],true); } else { createPath(out,[],[],true); }',
        '}'
    ].join('\n');
    function wipeFirstSel(comp){ var s=comp.selectedLayers; return s.length?s[0]:null; }
    function wipeAddControls(layer){
        var fx=layer.property("ADBE Effect Parade");
        var w=fx.addProperty("ADBE Slider Control"); w.name="Wipe"; try{ w.property(1).setValue(0);}catch(e){}
        var d=fx.addProperty("ADBE Angle Control"); d.name="Direction"; try{ d.property(1).setValue(90);}catch(e){}
        var rr=fx.addProperty("ADBE Checkbox Control"); rr.name="Radial"; try{ rr.property(1).setValue(0);}catch(e){}
    }
    function wipeAnimate(layer, fd){
        var sl=layer.property("ADBE Effect Parade").property("Wipe").property(1);
        var t1=WIPE_ANIM_FRAMES*fd; sl.setValueAtTime(0,0); sl.setValueAtTime(t1,100);
        try{ var ez=new KeyframeEase(0,33.3333); sl.setTemporalEaseAtKey(1,[ez],[ez]); sl.setTemporalEaseAtKey(2,[ez],[ez]); }catch(e){}
    }
    function wipeColorLink(ctrl, dup){
        var ramp=dup.property("ADBE Effect Parade").property("ADBE Ramp"); if(!ramp) return;
        var sc=ramp.property("ADBE Ramp-0002"), ec=ramp.property("ADBE Ramp-0004");
        var scv=[1,1,1,1], ecv=[0,0,0,1];
        try{ scv=sc.value; }catch(e){} try{ ecv=ec.value; }catch(e){}
        var fx=ctrl.property("ADBE Effect Parade");
        var c1=fx.addProperty("ADBE Color Control"); c1.name="Color 1"; try{ c1.property(1).setValue(scv);}catch(e){}
        var c2=fx.addProperty("ADBE Color Control"); c2.name="Color 2"; try{ c2.property(1).setValue(ecv);}catch(e){}
        try{ sc.expression='thisComp.layer("Wipe Controller").effect("Color 1")("Color")'; }catch(e){}
        try{ ec.expression='thisComp.layer("Wipe Controller").effect("Color 2")("Color")'; }catch(e){}
    }
    function wipeReveal1(){ if(!skHostSupported()) return;
        var comp=activeComp(); if(!comp){ alert("请先打开一个合成。"); return; }
        var content=wipeFirstSel(comp); if(!content){ alert("请选择内容图层。"); return; }
        var W=comp.width, H=comp.height, fd=comp.frameDuration;
        var cn=comp.name.replace(/\\/g,"\\\\").replace(/"/g,'\\"');
        var CTL='var ctl = comp("'+cn+'").layer("Wipe Controller");\n';
        var MATTE_EXPR=CTL+WIPE_MATTE_BODY, GLOW_EXPR=CTL+WIPE_GLOW_BODY;
        app.beginUndoGroup("Wipe Reveal 1");
        try{
            var ctrl=comp.layers.addNull(comp.duration); ctrl.name="Wipe Controller";
            wipeAddControls(ctrl); wipeAnimate(ctrl, fd);
            var matte=comp.layers.addSolid([1,1,1],"Wipe Matte",W,H,1,comp.duration);
            matte.moveBefore(content);
            var mask=matte.property("ADBE Mask Parade").addProperty("ADBE Mask Atom");
            try{ mask.maskMode=MaskMode.ADD; }catch(e){}
            mask.property("ADBE Mask Shape").expression=MATTE_EXPR;
            selectOnly(comp,matte); try{ matte.applyPreset(tempFFX(WIPE_MOSTURB_B64,"sk_wipe_mt.ffx")); }catch(ep){ alert("Mosaic/Turb 预设应用失败：\n"+ep.toString()); }
            try{ content.setTrackMatte(matte, TrackMatteType.ALPHA); }
            catch(e){ try{ content.trackMatteType=TrackMatteType.ALPHA; }catch(e2){} }
            try{ matte.enabled=false; }catch(eEn){}   // legacy AE needs the matte source hidden
            var pre=comp.layers.precompose([matte.index, content.index], "Wipe Reveal", true);
            var preLayer=null; for(var i=1;i<=comp.numLayers;i++){ if(comp.layer(i).source===pre){ preLayer=comp.layer(i); break; } }
            if(!preLayer){ alert("未找到预合成图层。"); app.endUndoGroup(); return; }
            preLayer.name="Wipe Reveal Main";
            var dup=preLayer.duplicate(); dup.moveAfter(preLayer); dup.name="Wipe Reveal Glow";
            try{ dup.startTime = dup.startTime - fd; }catch(e){}
            try{ skApplyPresetDG(comp,dup,tempFFX(WIPE_GRADGLOW_B64,"sk_wipe_gg.ffx")); }catch(ep2){ alert("渐变/发光预设应用失败：\n"+ep2.toString()); }
            skDeepGlow2(dup,{radius:321,exposure:1.06,ensure:true});
            wipeColorLink(ctrl, dup);
            var sub=dup.property("ADBE Mask Parade").addProperty("ADBE Mask Atom"); sub.name="Glow Wipe-out";
            try{ sub.maskMode=MaskMode.SUBTRACT; }catch(e){}
            sub.property("ADBE Mask Shape").expression=GLOW_EXPR;
            try{ sub.property("ADBE Mask Feather").setValue([280,280]); }catch(e){}
            try{ ctrl.moveBefore(preLayer); }catch(e){}
        }catch(err){ alert("擦除显现错误：\n"+err.toString()+(err.line?("\n（行号 "+err.line+")"):"")); }
        app.endUndoGroup();
    }

    function buildUI(thisObj){
        var pal=(thisObj instanceof Panel)?thisObj:new Window("palette","SaaS Kit",undefined,{resizeable:true});
        pal.orientation="column"; pal.alignChildren=["fill","fill"]; pal.spacing=6; pal.margins=8;
        var tp=pal.add("tabbedpanel"); tp.alignChildren=["fill","fill"]; tp.alignment=["fill","fill"];
        function mkTab(nm){ var t=tp.add("tab",undefined,nm); t.orientation="column"; t.alignChildren=["fill","top"]; t.spacing=4; t.margins=12; return t; }
        function btn(t,label,fn){ var b=t.add("button",undefined,label); b.onClick=fn; return b; }
        function hdr(t,txt){ var h=t.add("statictext",undefined,txt); try{ h.graphics.font=ScriptUI.newFont(h.graphics.font.name,ScriptUI.FontStyle.BOLD,h.graphics.font.size); }catch(e){} return h; }

        var tText=mkTab("Text");
        btn(tText,"Coloured Typing",typewriter1);
        btn(tText,"Random Letters",typewriter2);
        btn(tText,"Letter Rise",caCharacters);
        btn(tText,"Word Rise",caWords);
        btn(tText,"Typewriter",typewriter5);
        hdr(tText,"Exploder");
        btn(tText,"Explode Letters",explodeLetters);
        btn(tText,"Explode Words",explodeWords);
        btn(tText,"Explode Lines",explodeLines);

        var tFX=mkTab("FX");
        btn(tFX,"Carousel",carousel);
        btn(tFX,"Glass (shape)",glass);
        btn(tFX,"Number Counter",numberCounter);
        btn(tFX,"Wipe Reveal",wipeReveal1);

        var tCur=mkTab("Cursor");
        hdr(tCur,"Select a button");
        btn(tCur,"Cursor 1",function(){ insertCursor(CURSORS.c1); });
        btn(tCur,"Cursor 2",function(){ insertCursor(CURSORS.c2); });
        btn(tCur,"Cursor 3",function(){ insertCursor(CURSORS.c3); });

        var tDepth=mkTab("Depth");
        btn(tDepth,"Depth Reveal",function(){ depthReveal(SECOND_B64); });
        btn(tDepth,"Depth Reveal 2",function(){ depthReveal(SECOND2_B64); });
        btn(tDepth,"Depth Reveal 3",function(){ depthReveal(SECOND3_B64); });

        var tLayers=mkTab("Layers");
        hdr(tLayers,"Attach to selected");
        btn(tLayers,"Null",function(){ createBound("null"); });
        btn(tLayers,"Solid",function(){ createBound("solid"); });
        btn(tLayers,"Adjustment",function(){ createBound("adjustment"); });
        hdr(tLayers,"Expression");
        btn(tLayers,"Bounce",addBounce);

        var tBg=mkTab("Backgrounds");
        btn(tBg,"Gradient 1",function(){ insertGradient("Gradient 1"); });
        btn(tBg,"Gradient 2",function(){ insertGradient("Gradient 2"); });
        btn(tBg,"Gradient 4",function(){ insertGradient("Gradient 4"); });
        btn(tBg,"Gradient 5",function(){ insertGradient("Gradient 5"); });
        btn(tBg,"Gradient 6",function(){ insertGradient("Gradient 6"); });
        btn(tBg,"Gradient 7",function(){ insertGradient("Gradient 7"); });
        btn(tBg,"Gradient 8",function(){ insertGradient("Gradient 8"); });
        btn(tBg,"Star Gradient",function(){ insertGradient("Star Gradient"); });

        tp.selection=tText;
        pal.layout.layout(true);
        if(pal instanceof Window){ pal.center(); pal.show(); }
        return pal;
    }
/* buildUI disabled for CEP */
/* end CEP host */


